  str_mission_name_4220110 = "Arcana",
  str_mission_name_4220125 = "Lo misterioso",
  str_mission_desc_4001010 = "Por primera vez en 17 años, probaste tu habilidad psíquica. ¿Era esta joven ante ti una oportunidad de salir de este lugar?",
  str_mission_desc_4001020 = "Nunca antes habías visto tu gente, pero ahora tienes una amiga.",
  str_mission_desc_4001030 = "¿Quizá el Colossus estaba listo para ser activado?",
  str_mission_desc_4001040 = "Los Aurorians no dejarían de luchar mientras hubiera luz.",
  str_mission_desc_4001041 = "Cada vez había más Eclipsites. Será mejor intentar otros caminos si las cosas se ponen más difíciles.",
  str_mission_desc_4001042 = "Prueba",
  str_mission_desc_4001043 = "Prueba",
  str_mission_desc_4001044 = "Prueba",
  str_mission_desc_4001045 = "Prueba",
  str_mission_desc_4001046 = "Prueba",
  str_mission_desc_4001047 = "Prueba",
  str_mission_desc_4001050 = "Guiado por la Srta. Blanc, tendrás una idea más clara de cómo llegar al destino.",
  str_mission_desc_4001051 = "Luchaste más fácil en las batallas que antes. Los Aurorians y tú estaban trabajando muy bien ahora.",
  str_mission_desc_4001060 = "Tus batallas se volvieron más duras, viendo crecer a los Aurorians y a ti.",
  str_mission_desc_4001070 = "En el momento crítico, el suelo empezó a temblar y algo se acercaba...",
  str_mission_desc_4001080 = "Soroz no podía despegar ahora. Antes de poder funcionar, tenías que luchar contra incontables Eclipsites.",
  str_mission_desc_4001090 = "Los Eclipsites se han encontrado en todas las áreas de la Colossus. ¡Defiende hasta el final!",
  str_mission_desc_4001100 = "Un número creciente de Eclipsites invadió la vital sección de la Colossus: el Puente.",
  str_mission_desc_4001101 = "Algunas crisis desconocidas te acechaban.",
  str_mission_desc_4001110 = "Si no puedes ganar por números, los esquemas son el camino a seguir.",
  str_mission_desc_4001120 = "¡Debes irte con todos tus compañeros!",
  str_mission_desc_4001130 = "Acompañado por el rugido del motor, el Colossus salió disparado. Pero, un rival más fuerte que Kraken salió de la sombra.",
  str_mission_desc_4002015 = "El sacrificio de un aliado y la noticia inesperada... Todo esto parecía proyectar una sombra sobre el camino a seguir. ¿A dónde irá todo desde aquí?",
  str_mission_desc_4002010 = "Soroz se estrelló en el campo por una avería.",
  str_mission_desc_4002035 = "Prueba",
  str_mission_desc_4002020 = "Esta vez estarías al mando de un grupo de tipos torpes...",
  str_mission_desc_4002030 = "Rediesel Wrench era fuerte sin ninguna duda. Sin embargo, la fuerza de los Eclipsites lo llevó a un punto muerto.",
  str_mission_desc_4002031 = "¡Aguanta! Los refuerzos de Illumina podrían estar en camino. Tienes que resistir.",
  str_mission_desc_4002040 = "Teniendo en cuenta las posibilidades de combate y la lesión de Vice, los agresivos chicos de Rediesel Wrench te acorralaron.",
  str_mission_desc_4002050 = "La situación no parece muy buena. Los Eclipsites parecen estar atacando el Colossus...",
  str_mission_desc_4002060 = "Mientras todos suponían que un Eclipsite de alto nivel estaba a cargo, apareció un nuevo Eclipsite, Umbrahulk.",
  str_mission_desc_4002070 = "Comandados por Nozard, los Eclipsites amenazaron a los ciudadanos de Subciudad. Para conservar tus fuerzas, ¡no tenías más remedio que retirarte!",
  str_mission_desc_4002080 = "Los Eclipsites te atacaron desprevenido. Pero afortunadamente, no era demasiado tarde...",
  str_mission_desc_4002090 = "La Subciudad fue capturada por los Eclipsites. ¿Será el fin?",
  str_mission_desc_4002100 = "Subciudad 28 había caído, y en la mano de Charon estaba el medio final para acabar con los enemigos por completo.",
  str_mission_desc_4002101 = "¡Que los heridos y los ciudadanos se embarquen en la Colossus! ¡Aún no era el momento de relajarse!",
  str_mission_desc_4002110 = "El creciente peso de responsabilidad cayó en ti. Amigos, jefes y ciudadanos... ¿Qué rumbo seguir?",
  str_mission_desc_4002120 = "Al verse rodeado, Charon gritó con fuerza para urgirles a marcharse. Caería con la Subciudad 28...",
  str_mission_desc_4003010 = "Con la ayuda de Vice y Soroz, la búsqueda de tu gente pareció ir bien.",
  str_mission_desc_4003020 = "Uno de los tuyos te pidió ayuda. ¡¿Parecía haber caído en peligro?!",
  str_mission_desc_4003030 = "Parece que se te han adelantado. Hay rastros de Eclipsites por todas partes.",
  str_mission_desc_4003031 = "La señal no es buena. \"Esa Persona\" está siendo perseguida. Apúrate.",
  str_mission_desc_4003040 = "La llegada a las reliquias fue dura y cuesta arriba, acaparada por los Eclipsites.",
  str_mission_desc_4003050 = "Llegó una masa de Eclipsites. ¿Quién estuvo detrás de todo esto?",
  str_mission_desc_4003060 = "\"¡Lo encontraste! Pero estaba siendo perseguido por \nenemigos traidores\"",
  str_mission_desc_4003070 = "Nadie podía decir lo fuertes que eran tus enemigos. Aun así, no había vuelta atrás.",
  str_mission_desc_4003080 = "Schummer puso sus manos en el módulo Think Tank. Ya era tarde, ¡pero no escapará!",
  str_mission_desc_4003090 = "Mendelson estaba cada vez más débil, pero tú seguías avanzando sin dudar.",
  str_mission_desc_4003091 = "Te estabas acercando al destino. ¿Oliste a tus enemigos?",
  str_mission_desc_4003100 = "El aire estaba lleno de incertidumbres, cubierto por una densa niebla extendida en la oscuridad.",
  str_mission_desc_4003110 = "La energía oscura dominaba a Mendelson por completo. ¡Su cuerpo era como una vela al viento!",
  str_mission_desc_4003120 = "Rodeado de oscuridad y agitación, se escuchó un leve murmullo entre los Eclipsites de alto nivel. La prueba definitiva estaba por delante.",
  str_mission_desc_4004010 = "La zona este de la Baja Lumopolis fue invadida por Eclipsites. El tiempo es esencial y debes ganarlo.",
  str_mission_desc_4004020 = "¡Eclipsites fueron vistos en el área oeste! Los fugitivos levantaron al diablo por todas partes.",
  str_mission_desc_4004030 = "Era más Eclipsites de lo que pensabas. La evacuación y el asilo fueron antes que todo para la gente del pueblo.",
  str_mission_desc_4004031 = "Los guardianes estaban eliminando los restos de los Eclipsites. Ningún de ellos pudo escapar de su caza.",
  str_mission_desc_4004040 = "En un rincón remoto del área oeste, los Eclipsites convocados habían estado esperando\npor mucho tiempo.",
  str_mission_desc_4004050 = "Los Eclipsites atacaron una y otra vez, lo que podría ser solo un encubrimiento...",
  str_mission_desc_4004060 = "Shelt decidió hacer lo necesario para sus propios fines: despertó a su hermana, que también se había convertido en una Eclipsite...",
  str_mission_desc_4004070 = "Concéntrate en localizar a las hermanas Eclipsite y acabar con las plagas imprudentes.",
  str_mission_desc_4004080 = "Las hermanas Eclipsites no lo hicieron de improviso, convocando a los Eclipsites en un flujo interminable.",
  str_mission_desc_4004090 = "Se estaba acercando. Casi atrapas al cabecilla que planeó estos disturbios.",
  str_mission_desc_4004091 = "Mátenlos a todos. Ninguno se salvará.",
  str_mission_desc_4004100 = "¿Dónde estaba el hombre sospechoso? ¿Quién diablos era?",
  str_mission_desc_4004110 = "La sangre de las hermanas Eclipsite empañó esta ciudad. No tenían vuelta atrás.",
  str_mission_desc_4004120 = "Era hora de juzgar a las hermanas Cómo resistirán los desesperados enemigos...",
  str_mission_desc_4005010 = "El número de Colossus caídos indica el número de Celestitas sacrificados, así como el número de Eclipsites con sangre en sus manos...",
  str_mission_desc_4005020 = "El interior del Colossus caído sufrió graves daños, por lo que el camino hacia la Unidad de Crecimiento Autónomo fue accidentado y turbulento.",
  str_mission_desc_4005030 = "El peligro acechaba entre las reliquias. Los Eclipsites salieron de repente de las sombras.",
  str_mission_desc_4005031 = "Golpear el talón de Aquiles fue la clave para salir del peligro.",
  str_mission_desc_4005040 = "Esté atento. Podrías herirte a causa de los Eclipsites, así como por las trampas inadvertidas.",
  str_mission_desc_4005050 = "Una buena carnada puede salir ilesa con sus jugadas.",
  str_mission_desc_4005060 = "Una melodía piadosa sonó suavemente. El Colossus comenzó a brillar de nuevo desde su letargo. Este fue el último regalo, mi gente.",
  str_mission_desc_4005070 = "La llegada fortuita de la Colossus desordenó tus pensamientos. Es necesario reflexionar en las soluciones.",
  str_mission_desc_4005080 = "Los soldados perseguidores se desbordaban como moscas molestas a medida que pasaba el tiempo.",
  str_mission_desc_4005090 = "Solo quedan 5 minutos antes de la fecha límite. ¿Cuál fue tu decisión?",
  str_mission_desc_4005091 = "La evasión cuidadosa y las estrategias audaces eran indispensables.",
  str_mission_desc_4005100 = "Sé proactivo y no seas un blanco fácil.",
  str_mission_desc_4005110 = "Siempre había una forma y la verías si te adaptabas.",
  str_mission_desc_4005120 = "La cuenta regresiva iba a terminar. ¿Un ataque sorpresa cambiaría las cosas? ¡Era hora de dar un golpe mortal a Schummer!",
  str_mission_desc_4006010 = "Al perseguir el Módulo de Control de Llamas en el Pasillo Susurrante, has visto huellas de botas militares. Deben de ser del traidor, Gertzurde.",
  str_mission_desc_4006020 = "Para adelantarse a Schummer, aceleraste tu búsqueda.",
  str_mission_desc_4006030 = "Una emboscada enemiga tras otra mientras Carleen y Vice se esforzaban por encontrar el Módulo de Control de Llamas lo antes posible...",
  str_mission_desc_4006031 = "Oscuridad, frialdad y quietud... Luchar solo era insoportable, pero ¿realmente estabas sin apoyo?",
  str_mission_desc_4006040 = "Incluso con el apoyo remoto de la Sra. Sheol, los tortuosos giros del Pasillo Susurrante te sumergían en la confusión.",
  str_mission_desc_4006050 = "Gertzurde parecía estar al acecho. ¿Sería esta la batalla final?",
  str_mission_desc_4006060 = "\"¡Ustedes... mataron a Shelt!\" El vengador había aparecido antes que tú...",
  str_mission_desc_4006070 = "El Módulo de Control de Llama estaba cerca. Qué estaba tramando el enemigo...",
  str_mission_desc_4006080 = "El número de Eclipsites estaba aumentando, y las constantes luchas tenían a todos agotados...",
  str_mission_desc_4006090 = "Sin descanso... Los pasos de Gertzurde se acercaban y podías sentir el familiar aroma de la venganza.",
  str_mission_desc_4006091 = "Sin importar los obstáculos que enfrentaras, tus compañeros vendrían por ti sin importar los peligros...",
  str_mission_desc_4006100 = "No se detuvieron por las trampas y emboscadas en el camino. Había una pregunta que Gertzurde debía hacer a Schummer...",
  str_mission_desc_4006110 = "Por fin, han llegado a las profundidades del Pasillo Susurrante, y si no sucede nada \"inesperado\", el Módulo de Control de Llama debería estar aquí...",
  str_mission_desc_4006120 = "¿Conseguiría Gertzurde lo que quería? ¿Cumpliría Schummer su manifiesto de combate a muerte? Tu viaje casi había llegado a su fin.",
  str_mission_desc_4007010 = "Decidieron dividirse para garantizar que las operaciones de apoyo y rescate se llevaran a cabo al mismo tiempo.",
  str_mission_desc_4007020 = "Numerosos Eclipsites inundaron la Baja Lumopolis, pero tus operaciones parecían ir bien...",
  str_mission_desc_4007030 = "Te sentiste angustiado porque no podías sentir a Soroz, pero tenías que proteger los de la Baja Lumopolis, aunque no tenías capacidad de combate...",
  str_mission_desc_4007031 = "En este momento, algo se estaba gestando en Lumopolis...",
  str_mission_desc_4007040 = "En medio de la amenazas sobre tu cabeza y las salvajes batallas, esto fue una prueba que nunca has experimentado.",
  str_mission_desc_4007050 = "Operaciones de apoyo en Baja Lumopolis terminaron, pero la Zona residencial estaba siendo atacada...",
  str_mission_desc_4007060 = "Mientras se dirigían a la Zona residencial, apareció un enemigo familiar pero extraño, enorme y aterrador...",
  str_mission_desc_4007070 = "Esta fue una batalla por lo que todos querían proteger...",
  str_mission_desc_4007080 = "La batalla era un juego de vida o muerte que debía ganarse a contrarreloj.",
  str_mission_desc_4007090 = "El pánico aumentaba poco a poco. ¡No pueden dejar que los Eclipsites vuelvan a destrozar a Soroz!",
  str_mission_desc_4007100 = "Un mensaje de Soroz. ¡¿Podría ser...?!",
  str_mission_desc_4007110 = "La temperatura alrededor comenzó a descender rápidamente y se podía oler a Schummer, ¡allí!",
  str_mission_desc_4007111 = "¿El componente de 'auto-conciencia' de Soroz había desaparecido realmente? ¿Se desvanecería tu vínculo?",
  str_mission_desc_4007120 = "Schummer se convirtió en una persona totalmente diferente después de poseer todos los módulos. ¿Fue una batalla o sólo un juego unilateral?",
  str_mission_desc_4008020 = "Schummer te estaba reteniendo en Aviduz, así que Vice vino a salvarte. Decidieron buscar a la Jefa Vivian y llevarla con ustedes...",
  str_mission_desc_4008030 = "A medida que avanzaba, tu cuerpo se sentía extraño, pero no había tiempo para comprobar que pasaba. Tenías que encontrar a Vivian lo antes posible.",
  str_mission_desc_4008040 = "Caminaste con cuidado y te encargaste rápidamente de los enemigos en tu camino.",
  str_mission_desc_4008041 = "Engañados, cambiando lados y traicionando... Los Eclipsites serán sorprendidos con la guardia baja.",
  str_mission_desc_4008050 = "El Colossus Negro tenía una disposición interior compleja, así que había que tener mucho cuidado...",
  str_mission_desc_4008060 = "Schummer aún no te ha encontrado. Continúa, ¡quizás la Jefa Vivian esté en la habitación siguiente!",
  str_mission_desc_4008070 = "Mientras Curie abría paso, por fin llegaron a donde estaba retenida la jefa Vivian, y donde les esperaba un poderoso enemigo...",
  str_mission_desc_4008090 = "La Jefa Vivian fue rescatada con éxito, por lo que la tarea más urgente era abandonar este siniestro lugar. Pero, ¿era ésta realmente la opción más racional?",
  str_mission_desc_4008100 = "Sonó un ruido fuerte. La situación había cambiado. ¿¡Carleen tuvo éxito o Schummer finalmente triunfó!?",
  str_mission_desc_4008110 = "¡Tu estrategia cambió de escapar a atacar! ¡Esta era la última oportunidad de paralizar al enemigo desde dentro!",
  str_mission_desc_4008111 = "¿Qué pruebas y tribulaciones puedes esperar del siniestro Aviduz?",
  str_mission_desc_4008120 = "El camino al puente estaba lleno de peligro, y los Eclipsites bajaron frenéticamente...",
  str_mission_desc_4008130 = "Sigan moviéndose... ¡Schummer debe estar cerca!",
  str_mission_desc_4008140 = "Finalmente, llegó el momento decisivo. Lumopolis y el Colossus Negro; hoy uno caería, y tú serás testigo de todo...",
  str_mission_desc_4009020 = "Seguiste el rastro de escombros de Aviduz y te encontraste de regreso en Eraveil, donde todo comenzó.",
  str_mission_desc_4009030 = "¿Podría haber alguien más aquí además de los Eclipsites?",
  str_mission_desc_4009040 = "Aún más peligro acechaba, así como cierta cara familiar...",
  str_mission_desc_4009041 = "Encuentra sus debilidades y usa al enemigo para derrotar al enemigo.",
  str_mission_desc_4009050 = "Con Sinsa yendo a la fiesta, explorar Eraveil se convirtió en una tarea fácil.",
  str_mission_desc_4009060 = "La abundancia de Darkflow puede haber enfriado el aire, pero debes seguir adelante.",
  str_mission_desc_4009070 = "Las emociones fuertes cortan el aire. ¿De dónde vino ese grito? ¿Fue un Eclipsite?",
  str_mission_desc_4009090 = "El suelo tembló y un aura temible surgió...",
  str_mission_desc_4009100 = "¡Usa tus habilidades psíquicas para avanzar y encontrar la manera de romper la formación del enemigo!",
  str_mission_desc_4009110 = "Es como si los enemigos salieran de las paredes, e incluso parecían estar operando al unísono.",
  str_mission_desc_4009111 = "Si no puedes derrotar al enemigo de frente, intenta crear una oportunidad desde otro ángulo.",
  str_mission_desc_4009120 = "Apareció un enemigo difícil... ¡Es hora de librar a Eraveil de su malvada presencia!",
  str_mission_desc_4009130 = "Enemigo más fuerte estaba al acecho. Antes de afrontar la batalla que viene, debes escapar del asedio de Eclipsite.",
  str_mission_desc_4009140 = "¡Restos de Aviduz están delante! ¿Quién era ese que estaba parado frente a él?",
  str_mission_desc_4010020 = "Aviduz estaba justo frente a ti. Persiguiendo a Forsakin, confirmando si Schummer todavía está vivo... pase lo que pase después, tu única opción era entrar...",
  str_mission_desc_4010030 = "A través de tus habilidades psíquicas, dedujiste que Schummer... ¿había estado comiendo Eclipsites?",
  str_mission_desc_4010040 = "No todos los Eclipsites corrían por su vida… algunos de ellos estaban preparados para pelear contigo hasta la muerte.",
  str_mission_desc_4010041 = "Si alguna vez las probabilidades están en tu contra, ¡intenta hacer uso de tu entorno para cambiar la ventaja a tu favor!",
  str_mission_desc_4010050 = "Innumerables Eclipsites vagaban por Aviduz, como gusanos sin rumbo dentro de un cadáver enconado.",
  str_mission_desc_4010060 = "Los Eclipsites parecían estar empeñados en bloquear tu camino adelante.",
  str_mission_desc_4010070 = "Apareció otro enemigo familiar. Parecía que la magia de resurrección de Forsakin no podía subestimarse...",
  str_mission_desc_4010090 = "Al confirmar tu sueño sobre Eraveil, tu ira se encendió una vez más.",
  str_mission_desc_4010100 = "¡El enemigo parado frente a ti parecía poseer la habilidad de sellar Luminatics! Esta iba a ser una dura batalla.",
  str_mission_desc_4010110 = "Los Eclipsites que bloqueaban el camino no tenían intención de rendirse sin luchar.",
  str_mission_desc_4010111 = "Parecía que este flujo constante de Eclipsites no tenía fin.",
  str_mission_desc_4010120 = "¡Los Eclipsites trataban de llevarte a una situación sin esperanza!",
  str_mission_desc_4010130 = "Schummer estaba más adelante. No necesitabas usar tus habilidades psíquicas para saber esto—el suelo tembloroso y el desenfrenado Darkflow eran indicios suficientes.",
  str_mission_desc_4010140 = "¡Ganale a Schummer!",
  str_mission_desc_4101020 = "Oprimido por Darkflow, te enfrentas a más dificultades en la batalla. ¡Pero no puedes retroceder por la seguridad de Soroz!",
  str_mission_desc_4101030 = "En las profundidades de Entrañas, las huellas de la guerra están enterradas junto con otros secretos...",
  str_mission_desc_4101040 = "¿Cómo llegaron aquí los eclipses de alto nivel? ¡Correr! ¡No te detengas!",
  str_mission_desc_4101060 = "Reinhardt te ha estado observando. Para garantizar su seguridad, la ansiedad y las preocupaciones la han consumido.",
  str_mission_desc_4101070 = "¿Qué diablos pasó en Entrañas 80? Tal vez Reinhardt tenga una respuesta.",
  str_mission_desc_4101080 = "Pronto aterrizarás. ¿Habría esperanza de un regreso seguro esperando?",
  str_mission_desc_4101090 = "El odio duradero no se puede calmar fácilmente. A veces, irse puede ser la mejor opción.",
  str_mission_desc_4201020 = "¿Soroz está siendo emboscado por Eclipsites? Que no cunda el pánico. ¡Los sacaremos del Coloso!",
  str_mission_desc_4201030 = "El hecho de que Eclipsites lograra atacar a Soroz indica que alguien está detrás de todo esto. ¡Esto no fue una simple emboscada!",
  str_mission_desc_4201040 = "De todos modos, no es un accidente si aterriza donde se supone que debe hacerlo.",
  str_mission_desc_4201041 = "Encontrar Eclipsites mientras buscaba la entrada no era parte del plan, pero no hay tiempo que perder, eliminémoslos rápidamente.",
  str_mission_desc_4201050 = "Es bueno que tengas un detector de metales para ayudar a iniciar nuestra búsqueda de la entrada. Pero, ¿realmente puede encontrar algo útil?",
  str_mission_desc_4201060 = "Este lugar está vacío... Todo lo que queda son ecos y fragmentos del pasado.",
  str_mission_desc_4201061 = "Continúa explorando y buscando... Hagamos todo lo posible para encontrar la luz de la esperanza en las profundidades.",
  str_mission_desc_4201070 = "Una presencia desconocida observa la batalla y sigue todos tus movimientos.",
  str_mission_desc_4201080 = "No te detengas y no mires atrás. Sigue corriendo hacia adelante y buscando ese lado positivo.",
  str_mission_desc_4201090 = "¿Qué actos malvados debe uno cometer para ser desterrado a tal abismo?",
  str_mission_desc_4201100 = "No es aquí, sino más profundo. Siga avanzando, pero tenga cuidado con las amenazas del pasado.",
  str_mission_desc_4201120 = "Caelestites, Aurorians, Eclipsites, Colossi... Me pregunto cuántos secretos se esconden en esta vasta base abandonada hace mucho tiempo...",
  str_mission_desc_4201130 = "No son solo los muros y las puertas de la base los que guardan estos secretos, sino también esos Eclipsites aquí.",
  str_mission_desc_4201140 = "El Neural Aux está dañado y no hay forma de ingresar comandos correctamente. ¿Qué tal... reiniciarlo primero?",
  str_mission_desc_4202020 = "Parece que hay eclipses en esta torre. ¿Estaban ya aquí para empezar?",
  str_mission_desc_4202030 = "A medida que avanza, se encuentra con algo desconocido e inesperado.",
  str_mission_desc_4202040 = "Has estado escuchando ruidos extraños detrás de ti desde hace un tiempo. ¿Están los eclipses siguiendo tu rastro... o algo más?",
  str_mission_desc_4202041 = "¿Desde cuándo los eclipses se han vuelto lo suficientemente inteligentes como para usar trampas? ¡Mantén los ojos abiertos y derrotémoslos!",
  str_mission_desc_4202050 = "¡¿Qué pasa con todas estas trampas que conducen a la Zona de Acordes?! Me pregunto si podrían ser utilizados...",
  str_mission_desc_4202060 = "Barton decidió usar Chord Link para escapar de esta difícil situación. ¡Haz lo que puedas para comprarle algo de tiempo!",
  str_mission_desc_4202070 = "Tranquilo ahí... Sólo un poco más y las cosas se volverán a tu favor.",
  str_mission_desc_4202090 = "La batalla se libra fuera de la torre y los refuerzos finalmente han llegado. Ahora todo lo que queda es luchar.",
  str_mission_desc_4202100 = "Todos lo dan todo en el campo de batalla, pero ¿cuánto tiempo pueden resistir?",
  str_mission_desc_4202115 = "Los aurorianos fuera del Obelisco del Retorno están haciendo todo lo posible para encontrar una oportunidad de cambiar el rumbo.",
  str_mission_desc_4202111 = "Parece que un alborotador ha entrado en el campo de batalla. El tiempo se acaba. ¡Vamos a atacar, ahora!",
  str_mission_desc_4202120 = "Todavía hay eclipses que bloquean el camino hacia el Core Ring e incluso desafíos más difíciles por delante.",
  str_mission_desc_4202130 = "Hay algunas cosas que solo tú puedes hacer. Todo el mundo está aquí, listo para ayudar, así que hazlo.",
  str_mission_desc_4202140 = "Es un llamado a regresar, no solo por ti, sino por la esperanza.",
  str_mission_desc_4203020 = "Para comprender mejor la condición de Vice, acepta permitir que Illumina investigue nuevos módulos de datos encontrados en Soroz.",
  str_mission_desc_4203030 = "Después de ingresar al campo de batalla simulado, comienza a realizar pruebas de acuerdo con las instrucciones de los investigadores. Como mínimo, las batallas son bastante fáciles... por ahora.",
  str_mission_desc_4203040 = "Usas el simulador de batalla una vez más, pero esta vez el terreno y el entorno han cambiado.",
  str_mission_desc_4203041 = "Hay caos y peligro por todas partes, y estás completamente perdido... ¡No puedes permitirte quedarte aquí mucho más tiempo!",
  str_mission_desc_4203050 = "Aférrate. ¡Nadie dijo que la simulación iba a ser tan difícil!",
  str_mission_desc_4203060 = "¿Qué es este lugar? ¿Por qué no lo he visto antes? ¿Vicio? ¿Reinhardt? ¿Pueden oírme?",
  str_mission_desc_4203070 = "Soldados desesperados siendo aplastados bajo un ataque salvaje de Eclipsite... ¿Es este el fin del mundo?",
  str_mission_desc_4203090 = "Guardian One, responsable de la totalidad de las operaciones diarias de la Federación Illumina... parece más pequeño de lo esperado.",
  str_mission_desc_4203100 = "A pesar de que esta es la primera vez que se encuentra con Guardian One, se establece un sentido puro y natural de confianza entre ustedes dos.",
  str_mission_desc_4203110 = "Es imposible pararse con ambos pies sobre suelo firme en un entorno virtual. Aun así, tu única opción es seguir avanzando.",
  str_mission_desc_4203111 = "Este experimento busca poner a prueba los límites de la propia fuerza para descubrir hasta la más mínima posibilidad de romperlos.",
  str_mission_desc_4203120 = "Extienda su mano, corra más rápido, está a solo un paso de alcanzarlo.",
  str_mission_desc_4203130 = "Es hora de arreglar las cosas. Después de todo, es por eso que viniste aquí en primer lugar.",
  str_mission_desc_4203140 = "Después de una cantidad de tiempo indeterminada, finalmente llegas al problema técnico final.",
  str_mission_desc_4204020 = "El arma poderosa e importante conocida como \"Combat Cyborg\" es en realidad...",
  str_mission_desc_4204030 = "Sean regresa de la zona de guerra lo más rápido que puede. Recibió noticias de la guarnición Illumina de que estabas en camino.",
  str_mission_desc_4204031 = "A veces, cargar directamente al combate no es la mejor opción.",
  str_mission_desc_4204040 = "Continúas tu viaje a Crepúsculo, donde finalmente se reúnen tres viejos amigos.",
  str_mission_desc_4204050 = "Después de llegar finalmente a las afueras de Crepúsculo, la aurora comienza a salirse de control, lo que significa un desastre para los que viven debajo.",
  str_mission_desc_4204060 = "¡Todavía hay civiles detrás de ti tratando de escapar! ¡No dejes que te pase ni un solo Eclipsite!",
  str_mission_desc_4204070 = "Un rayo de luz ilumina repentinamente el campo de batalla, permitiéndote a ti y a tus aliados luchar sin restricciones.",
  str_mission_desc_4204090 = "Tú y tus aliados finalmente estáis listos. La oscuridad ya no impedirá tu vista.",
  str_mission_desc_4204100 = "Lo que has estado buscando... ¿Dónde podría estar?",
  str_mission_desc_4204101 = "¡Encuentra el punto débil, apunta bien y concentra tus ataques!",
  str_mission_desc_4204115 = "¿Quién es más poderoso: Axelia o Sean?",
  str_mission_desc_4204120 = "Después de una gran cantidad de dificultades, finalmente encuentras el Coloso que se estrelló en ruinas. La victoria está al alcance de la mano.",
  str_mission_desc_4204130 = "Inmediatamente después de copiar sus datos, el Coloso comienza a moverse. ¿Se avecina otra catástrofe?",
  str_mission_desc_4204140 = "Un último poema, ofrecido en tu nombre... Un último adiós.",
  str_mission_desc_4205020 = "Forsakin te obliga a luchar contra los soldados de Illumina.",
  str_mission_desc_4205030 = "Una vez más te encuentras con centinelas en la entrada del laboratorio.",
  str_mission_desc_4205040 = "Usted y Vice no van a juguetear con sus pulgares mientras continúa el experimento. Esperar el momento adecuado para revertir el predicamento...",
  str_mission_desc_4205041 = "¡Aprovecha la oportunidad de derrotar al enemigo y escapar!",
  str_mission_desc_4205050 = "¡Tu resistencia ha sido Eclipsites convocada por Forsakin en un ardiente duelo a muerte!",
  str_mission_desc_4205070 = "Separado de Vice, tu yo solitario no tiene más remedio que obedecer a Forsakin. Debes seguir su voluntad y aventurarte en las profundidades de Entrañas.",
  str_mission_desc_4205080 = "Para localizarte a ti y a Vice, quien ha estado desaparecido durante mucho tiempo, Carleen sigue los consejos de Gronru para Entrañas.",
  str_mission_desc_4205090 = "Todavía buscando los archivos, Forsakin no esperaba fuertes defensas en el Archivo de archivos.",
  str_mission_desc_4205100 = "Encargada de una misión importante, Yingel finalmente encontró el paradero de Vice, solo para encontrarse con un enemigo formidable antes del rescate...",
  str_mission_desc_4205101 = "Algunos enemigos te enfrentarán en una pelea larga y mortal, así que ten cuidado...",
  str_mission_desc_4205110 = "Yingel está librando una dura batalla, mientras Carleen ha llegado a Forsakin e intentará sacarte de aquí.",
  str_mission_desc_4205120 = "Forsakin pierde el equilibrio por el fuego sorpresa. ¡Aprovecha la oportunidad para derrotarla a ella ya Helios!",
  str_mission_desc_4205130 = "Justo cuando estás a punto de derrotar a Forsakin, ella lo frustra cortando la energía de la puerta principal...",
  str_mission_desc_4205140 = "Forsakin ha completado la actualización final a Helios. Va a ser una pelea brutal.",
  str_mission_desc_4206020 = "La primera sesión es una lucha virtual a través de Battle Simulator, y todos los participantes del ejercicio se están preparando seriamente.",
  str_mission_desc_4206030 = "La segunda sesión son lecciones de combate, con un equipo de personal de entrenamiento dirigido por Wrath transmitir conocimientos de lucha a los participantes del ejercicio...",
  str_mission_desc_4206040 = "Para obtener más créditos de curso, usted, Vice, y Carleen decida solicitar permisos de simulador adicionales para perfeccionar sus habilidades de combate.",
  str_mission_desc_4206041 = "¡Los enemigos parecen alimentarse de la batalla! ¡Tiene que haber una forma de acabar con la lucha!",
  str_mission_desc_4206050 = "Antes de que comenzara el ejercicio, los eclipses de quién sabe dónde surgieron repentinamente en la ciudad de Gannon. Deshágase de ellos lo antes posible.",
  str_mission_desc_4206060 = "La tercera sesión del Ejercicio Militar Conjunto está luchando contra verdaderos Eclipsites en un combate real. ¿Prevalecerán los participantes contra tantos enemigos?",
  str_mission_desc_4206070 = "Al llegar al sitio para capturar la bandera, los escuadrones se dividen y van a Entrañas. Sin embargo, tu escuadrón se ve envuelto en una pelea inesperada contra Eclipsites.",
  str_mission_desc_4206080 = "La caótica batalla continúa y ese extraño escuadrón demuestra ser bastante duro...",
  str_mission_desc_4206090 = "Te adentras más en Entrañas hasta encontrarte al azar con un peligro aún mayor en forma de una enorme monstruosidad con forma de araña.",
  str_mission_desc_4206110 = "Tú, Yingel, y otros se separaron para ver a Gannon. ¡Efectivamente, te encuentras con Eclipsites que se deslizan a través de la brecha en las defensas!",
  str_mission_desc_4206120 = "Los intrusos de Eclipsite se dispersan presas del pánico, aparentemente sin intención de luchar. También sientes la amenaza familiar de cierto Wraith...",
  str_mission_desc_4206121 = "Los intrusos todavía están presentes en la ciudad que deben ser eliminados lo antes posible.",
  str_mission_desc_4206130 = "Siguiendo los rastros de Wraith, llegas a cierta puerta en el nivel más bajo. Figerald busca algo allí. ¡Detenlo!",
  str_mission_desc_4206140 = "Los peones están todos fuera del camino. ¡Ahora vamos con Figerald el Espectro!",
  str_mission_desc_4207020 = "Tú y Vice llegan a la oficina de los Comandantes de la Legión de Illumina, con la esperanza de tener la oportunidad de cambiar el rumbo. Sin embargo, antes de que puedan hablar, los comandantes ya han recibido órdenes de misión y se han ido...",
  str_mission_desc_4207030 = "Los ciudadanos de Illumina están emocionados con lo que ha estado sucediendo últimamente. Justo cuando te das cuenta de esto, un anuncio resuena en las transmisiones de la Ciudad Subterránea, proclamando la ascensión de un nuevo Gran Mariscal...",
  str_mission_desc_4207031 = "Los Eclipsites pronto se liberarán de donde han estado confinados. ¡Derrotarlos por la seguridad del laboratorio!",
  str_mission_desc_4207040 = "Recién ascendida a Gran Mariscal de Illumina, Wrath ya ha sido asignada para reforzar el frente de batalla en Crepúsculo. Sin embargo, mientras se prepara para partir, parece no haber sentido ninguna de la alegría anticipada de convertirse en la Gran Mariscal...",
  str_mission_desc_4207050 = "Reflexionando sobre el pasado, Wrath ha iniciado innumerables desafíos contra Reinhardt, casi todos los cuales terminaron en fracaso, incluida la selección final para Gran Mariscal...",
  str_mission_desc_4207060 = "Joselyne guía a los heridos hacia un lugar seguro. Sin embargo, al enterarse de la falta de confianza de los soldados en el campo de batalla, ella reflexiona sobre qué puede hacer por ellos...",
  str_mission_desc_4207080 = "Con tus habilidades psíquicas, percibes que el Darkflow omnipresente en el Crepúsculo parece ser maniobrado por un mando central. Sin embargo, el enemigo principal en este centro aún está envuelto en misterio...",
  str_mission_desc_4207090 = "La llegada de los soldados de Illumina detiene momentáneamente las acciones de los Eclipsites, pero Forsakin parece haber detectado el secreto detrás de la fuerza mejorada de estos soldados...",
  str_mission_desc_4207100 = "Mientras la batalla contra los Eclipsites continúa, una ola de acciones anormales se propaga entre los soldados Illumina. Se especula que los soldados podrían estar influenciados por algún enemigo que actúa como el mando central...",
  str_mission_desc_4207110 = "Preocupada por Axelia en el campo de batalla, Yingel se dirige al laboratorio de Ulysses. Dentro de estas paredes, ella es testigo de un cruel experimento...",
  str_mission_desc_4207111 = "Los monstruos en los pantanos han bloqueado tu camino. ¡Derrotalos!",
  str_mission_desc_4207120 = "Enfrentado al lodo que se extiende cada vez más y a los ataques de los Eclipsites, Wrath toma una decisión firme: sumergirse en el barro en busca del enemigo de mando central que se esconde en él...",
  str_mission_desc_4207130 = "Después de enfrentarse al enemigo del comando central, el cuerpo de Wrath gradualmente se escapa de su control. Soroz especula que su conciencia ha sido engullida por el lodo...",
  str_mission_desc_4207140 = "El escuadrón de Axelia ha estado atrapado en el barro durante bastante tiempo. En este momento, Axelia ya ha perdido la capacidad de atacar a los Eclipsites, pero sus labios siguen murmurando dos comandos de acción especiales...",
  str_mission_desc_4208020 = "Con el Eclipsite de lodo derrotado, te embarcas en una búsqueda exhaustiva de la ubicación de Wrath. Sin embargo, en este mismo momento, también comienzan a manifestarse cambios inesperados entre los soldados de Illumina...",
  str_mission_desc_4208030 = "La sensación de alivio te inunda con el regreso de Wrath, pero sus pruebas te dejan perplejo. Posteriormente, el enfoque colectivo se dirige hacia la difícil situación de los soldados heridos...",
  str_mission_desc_4208040 = "El escuadrón de rastreo liderado por Charon y Vice encuentra una resistencia peculiar, impidiéndoles llegar a la Zona Oscura. Mientras tanto, a bordo del tren, aparece un misterioso pasajero...",
  str_mission_desc_4208041 = "La situación se está descontrolando. Los enemigos ahora te apuntan a ti; por favor, protege a tus compañeros de equipo.",
  str_mission_desc_4208050 = "Victoria ha llevado al grupo a evadir temporalmente la persecución de la enigmática fuerza. Sin embargo, en este preciso momento, la Biblia Sangrienta trae una nueva revelación...",
  str_mission_desc_4208060 = "Mientras Wrath busca a sus subordinados, un soldado desorientado la agarra del cuello. Todos intentan hacerla entrar en razón, pero ella aún no puede decidirse...",
  str_mission_desc_4208070 = "Joselyne suplica a la Fortaleza Lumo que refugie a los desplazados, pero solo encuentra rechazo. Sin embargo, justo cuando los soldados heridos comienzan a atacar a los inocentes, una poderosa voz resuena...",
  str_mission_desc_4208080 = "A medida que la operación de búsqueda llega a las barreras de Crepúsculo, una vista asombrosa se despliega ante los ojos del grupo. Y el cerebro detrás de todo, por fin, finalmente aparece...",
  str_mission_desc_4208100 = "Con el barro disipado, Crepúsculo se queda con nada más que paredes destrozadas y ruinas. Sin embargo, enfrentándose a estos escombros desordenados, Leo y Joselyne parecen tener nuevas esperanzas para el futuro del pueblo.",
  str_mission_desc_4208110 = "A lo largo de la línea defensiva de Illumina, Sharona lidera la 1ª Legión, intentando repeler a los Eclipsites. Sin embargo, la repentina inundación de pantanos y los ataques de compañeros soldados provocan pánico entre las filas...",
  str_mission_desc_4208111 = "¡Limpia los atolladeros con el refuerzo de artillería!",
  str_mission_desc_4208120 = "Mientras Forsakin lidera a los pantanos en un asalto a la línea defensiva de Illumina, un inquietante coro de ruedas chirriantes y cascos galopantes resuena desde la dirección de Crepúsculo...",
  str_mission_desc_4208130 = "La feroz batalla continúa, con soldados Illumina desorientados lanzando ataques sin parar contra tu bando...",
  str_mission_desc_4208140 = "Mientras los comandantes de Illumina analizan la situación actual, Forsakin, al recibir la señal de retirada de Eclipse, decide asestar un golpe final a los soldados de Illumina...",
  str_mission_desc_4001010_long = "Te limitaste a activar el Colossus, a pesar de que lo has intentado durante 17 años en vano.\nVice, una chica Aurorian, apareció de repente en el Colossus cuando lo intentabas de nuevo.\nVice prometió que te sacaría de aquí una vez que derrotaras a los Eclipsites con tu habilidad psíquica.\n¿Podrías finalmente salir del Colossus?",
  str_mission_desc_4001020_long = "Volviste a derrotar a los Eclipsites con tu habilidad.\nTú y el equipo de Vice eran amigos ahora.\nNo podía creer que tuvieras amigos incluso antes de visitar el mundo de ahí fuera.",
  str_mission_desc_4001030_long = "Dado que el comunicador se dañó, los Eclipsites te superaban en número sin soporte.\nQuizá todos se salvarían si activaras la Cámara de Estrellas.",
  str_mission_desc_4001045_long = "Perdiste el conocimiento por usar en exceso tu habilidad psíquica para controlar el Colossus.\nOtra Aurorian, la Srta. Blanc, se sumó como refuerzo.\nAdemás, los marcadores de señal atrajeron a una multitud de Eclipsites.\nNo tuviste opción más que empezar a moverte y encontrar una salida.",
  str_mission_desc_4001050_long = "En poco tiempo, encontraste el objetivo de Charon, Zoya, una ingeniera, en la estación base.\nAparte de Zoya, aún faltaba un joven.\nNo podías hacer la vista ciega, así que cruzaste un grupo de Eclipsites para buscarlo.\n¡Afortunadamente, aún estaba vivo!\nSolo que descubriste que estaba herido y que \"él\" era en realidad una niña.",
  str_mission_desc_4001060_long = "Finalmente, ingresaste a la Subciudad 28.\nCharon te hizo entrar a ti y a los forasteros, aunque fue bastante severo.\nDespués de derrotar a los que escaparon, atracaste a Soroz en el puerto.\nA pesar de los recursos limitados en la Subciudad, el Colossus se estaba reponiendo y se estaba recuperando lentamente.\nCon el descanso merecido, te sentiste aliviado y... desmayaste.",
  str_mission_desc_4001070_long = "Los Aurorians y tú derrotaron juntos al enorme Eclipsite Kraken de alto nivel.\nNo era hora de celebrar porque un fuerte ejército de Eclipsites les estaba esperando.\nPara una evacuación segura y visitar el nuevo mundo...\nVice decidió intentar reactivar el Colossus contigo.",
  str_mission_desc_4001095_long = "Tú y Vice controlaron el Colossus juntos. Cuando el motor arrancó... Soroz, envuelto en Aurora, despertó de verdad.",
  str_mission_desc_4001080_long = "El calentamiento era necesario para Soroz que estuvo sin usar durante 17 años.\nSin embargo, se expuso indefenso ante Eclipsites.\n¡Defender el Colossus es la máxima prioridad!",
  str_mission_desc_4001090_long = "La operación imposible de rescate era demasiada difícil.\nJamás abandonar y nunca rendirse. ¿Podrías hacerlo?\nEl sonido explosivo lejano incomodó a Vice y a ti.\n¿Qué pasó con Charon?",
  str_mission_desc_4001100_long = "La anormalidad se estaba acercando desde donde Charon era responsable.\nApresúrense a su destino y prepárense para luchar contra oponentes formidables.\nCharon y Dayna tenían mucha razón. ¡Estaban todos reunidos!\nHabía un rayo de esperanza en una situación desesperada:\nSoroz estaba atracado en el puerto cercano.",
  str_mission_desc_4001110_long = "Soroz, como esperanza en la adversidad,\niba a ayudarte a escapar.\nNadie sabía si habría mayores desafíos.\nNo hubo tiempo para cargarse con dificultades impredecibles. Protege a los heridos y a tus compañeros para ayudarlos a embarcar en el Colossus ahora.\n¡Recorta las velas!",
  str_mission_desc_4001120_long = "Fuiste gravemente herido por los feroces ataques de Eclipsites.\nAlgunos de tus compañeros cayeron en la batalla, mientras que el resto luchó desesperados por vivir.\nEsperarte fue una batalla cuesta arriba.",
  str_mission_desc_4001130_long = "Soroz despegó ante la mirada de todos.\nPero, en el Colossus apareció otro Eclipsite de alto nivel, Nozard.\nBombardeados con batallas, todos estaban demasiado cansados para luchar.\nAlgunos de tus compañeros sacrificaron sus vidas para que el resto pudiera sobrevivir...",
  str_mission_desc_4002015_long = "Dado que todos ustedes estaban fuera de peligro ya, Vice los convenció de que volvieran a Illumina con ella primero. \nAl dudarlo, Soroz, que estuvo más de 17 años sin uso, se vio obligado a aterrizar debido a una avería. \nPor otro lado, Nozard sobrevivió y no renunció a perseguirlos...",
  str_mission_desc_4002010_long = "El fuerte ruido del Colossus que caía, atrajo innúmeros Eclipsites.\nSe acercaba una nueva batalla.",
  str_mission_desc_4002035_long = "Vice resultó gravemente herida por protegerte de los Eclipsites cuando discutías con ella.\nEn la coyuntura crítica, un grupo de ladrones que afirmaban ser Sinsa derrotaron a los Eclipsites.\nFuiste salvado, pero afirmaron que el Colossus era entonces de ellos.",
  str_mission_desc_4002020_long = "Se acercaba otra batalla. Pero tenías que contar con los tipos no identificados de Rediesel Wrench.\n¡Fue genial saber que estos bandidos podían luchar tan bien como los Aurorians!",
  str_mission_desc_4002030_long = "Se acercaba otra batalla. Pero tenías que contar con los tipos no identificados de Rediesel Wrench.\n¡Fue genial saber que estos bandidos podían luchar tan bien como los Aurorians!",
  str_mission_desc_4002040_long = "¿Lo hizo Sinsa en un momento de debilidad o tenía un hacha para moler?\nNo tenía nada que decir en este asunto, excepto para ver qué pasaría a continuación.\nTe llevó a la base de Rediesel Wrench.\nEsta calle, Tail Street, estaba llena de desesperos y corrupción.\n¿Por qué te trajo aquí?",
  str_mission_desc_4002050_long = "El mundo era jerárquico y siempre había rincones oscuros que nunca conociste\nEl hecho es que tú y Vice tenían una nueva compren. de Rediesel Wrench...\nDescubriste al menos uno de los propósitos de Sinsa:\nQuerían purgar a los no principiantes con la ayuda de Soroz.",
  str_mission_desc_4002060_long = "La batalla despegó, pero todos se preguntaron por qué los Eclipsites podían luchar con determinación y de forma orgánica.\n¡La presencia de Umbrahulk demostró que tenían razón!\nJusto cuando llegó los refuerzos de Illumina, los chicos de Rediesel Wrench se fueron con mucho tacto.\nUna vez más, tu destino fue decidido por otra persona.",
  str_mission_desc_4002095_long = "Regresaste a Subciudad 28 con Charon. Vice y Soroz que se establecieron bien.\nLa defensa era impenetrable, pero Charon e Hiiro todavía sospechaban que los Eclipsites habían descubierto el camino para cruzarla.\nUnos días después, Vice se recuperó. El breve descanso fue interrumpido por una nueva crisis:\nLa ciudad subterránea comenzó a temblar y se disparó la alarma. ¡¿Qué pasó?!",
  str_mission_desc_4002070_long = "Los Eclipsites atravesaron la defensa en la esquina fuera de la vista de la Subciudad, y todo estaba en peligro.\nLa mejor forma de proteger a los heridos y los ciudadanos era retirarse. Solo pudiste lanzar un plan de contingencia\nAlgún misterio subyace en este asunto, pero no tuviste tiempo para pensarlo.",
  str_mission_desc_4002080_long = "Sinsa y Eve vivieron una vez en una Subciudad antes.\nEve también se redujo a \"dicha mirada\" allí.\n¿Cuál era la verdad?\n¿Qué podría decirnos la historia?\nAhora, solo podías seguir los pasos de Sinsa y completar sus dos solicitudes...",
  str_mission_desc_4002090_long = "Quedaste abrumado por olas de ataques de los Eclipsites.\nSi continuara así, ¡todo el mundo estaría en gran peligro!\nHabiendo enfrentado problemas similares, se te ocurrió una idea: la última esperanza era el Colossus.",
  str_mission_desc_4002100_long = "Los Eclipsites se habían reunido alrededor del Colossus. Será mejor que te retires y destruyas toda la info. de la Subciudad lo antes posible.\n¡Pero ahora, no era el momento de presionar la llave roja!",
  str_mission_desc_4002110_long = "Todos estaban en el Colossus, excepto Charon.\nNo podías dejar a Charon allí así, pero estabas muy cansado de las batallas.\nEl cruel abandono era inevitable, sin importar la elección que hicieras...",
  str_mission_desc_4002120_long = "Se presionó la llave roja. ¡Retírate ahora!\nDerrotaste a Nozard, que se levantó de una vez por todas cuando rompió el asedio y huyó.\nLa Subciudad 28 se convirtió en humo. Mientras llorabas por Charon...\nUn tren de alto vuelo salió del fuego; ¡¿Fue Charon?!",
  str_mission_desc_4003015_long = "Antes de que llegaran los refuerzos, sentiste un llamada de ayuda de un joven. ¿Era uno de tu gente?\n¡Intentaste aprovechar la pequeña oportunidad de descubrir la verdad, aunque fue una decisión peligrosa!\nVice decidió estar a tu lado esta vez. El Celestita ya no necesitaría luchar solo.",
  str_mission_desc_4003010_long = "Una estela recién construida estaba en los acantilados mientras el sol brillaba como de costumbre.\nNi tú ni Sinsa se libraron del sentimiento de anhelo.\nLos nuevos cambios te han sorprendido Las tropas de Illumina rompió la quietud.\nVice y tú volvieron al equipo después de resolver el inesperado ataque de Eclipsites.\nLos chicos de Rediesel Wrench se fueron, desapareciendo en el desierto...",
  str_mission_desc_4003020_long = "Mendelson, que protegía el Módulo Think Tank, fue atacado por Schummer.\nA pesar de sus mejores esfuerzos por resistir, su cuerpo destro. y desgarrado no pudo cambiar su destino.\nSin los soldados, se vio obligado a retirarse y solo pudo pedir tu ayuda mientras huía.",
  str_mission_desc_4003030_long = "“El tiempo se acaba\", pidió ayuda el misterioso joven.\nLas excavaciones de Colossus en la Reliquia ES-0096-F7 se paralizaron inesperadamente. Hiiro también desapareció\nTú y Vice activaron a la fuerza el Colossus para buscar a tu superior.\nNo solo para demostrar tu hab. para comandar el Colossus\npero también más para salvar a tus compañeros.",
  str_mission_desc_4003031_long = "TBC",
  str_mission_desc_4003040_long = "¡Los miem. del equipo de excav. fueron asim. dentro de los Eclipsites!\nTenías que recupe. para luchar contra tus antiguos compa.\nMientras tanto, el cortafuegos de reliquias Aurorian fue corroído por el poder oscuro.\nLa Gran Aviduz anunció con su gran poder que purgaría las traiciones y buscaría veng. por Madre.",
  str_mission_desc_4003050_long = "No pudiste salvar al último sobrev. El oscurec. estaba condenado a terminar así.La lluvia de flores pod. salvar su alma...Sakura limpió su cuer. y plantó la fe Aurorian en su conciencia.Te dijo un mensaje importante, que \"ellos\" aún están aquí.",
  str_mission_desc_4003060_long = "Final. encon. a Mendelson que está gravem. herido.\nFue capturado por sus propios soldados debido al fuerte poder de Schummer.\nBatalla inminente—",
  str_mission_desc_4003070_long = "Una actua. parecía haber term. en secreto en otro lugar.\nSin embargo, Schummer quería llevar la act. a otro clímax, para inyectar Darkflow infinito en el núcleo del Colossus.\nVice percibió algo, aunque estaba nublado.\nSolo tendrías que tocarlo de oído. Intuit., podrías encontrar un camino hacia el final de la actuación.",
  str_mission_desc_4003080_long = "Tenías miedo, pero morir con dign. venció a vivir en desgracia.\nEl Celestita fue exterm. ¡Así que sobre todo es defender el futuro de todos los demás!\nSchummer puso sus manos en el Módulo Think Tank. Ahora es solo el tiempo antes...\n¡Tenías que seguir adel. para terminar todo esto!",
  str_mission_desc_4003090_long = "La figura en tu mente ahora estaba parada frente a ti, luciendo extraña pero familiar. El frágil joven era ECO de la reliquia Colossus, Mendelson. Mientras tanto, Hiiro y Zoya fueron enterradas entre los escombros de las ruinas. El rugido agonizante de Colossus resonó con fuerza en las ruinas. Tuvieron que acelerar el paso en caso de un segundo colapso.",
  str_mission_desc_4003091_long = "TBC",
  str_mission_desc_4003100_long = "La mayoría de los sistemas se desconectaron debido al daño causado por Schummer. Fue difícil localizar a Hiiro y Zoya. Tuvieron que escapar con su ingenio. Tú y Vice fueron a completar una misión más importante con Mendelson.",
  str_mission_desc_4003110_long = "Estabas en el lugar donde se almacenaba el Módulo Think Tank, y Schummer...podría estar esperándote aquí.¡Deténla! Afectado por la energía oscura, el cuerpo de Mendelson se volvió cada vez más débil. Quizá... esta sería su última pelea.",
  str_mission_desc_4003120_long = "Schummer se había ido y Tabaad te esperaba allí. Gracias a la ayuda de Hiiro, el cuerpo de Tabaad se desvanecía en la sakura. Abrazando la última visión, la vida de Mendelson llegó a su fin, dejándote pistas: El Módulo Think Tank, la Unidad de Crec. Autónoma y el Módulo de Control de Llama: estos serán lo que seguirá Schummer a continuación...",
  str_mission_desc_4003145_long = "En este mom., en el arch. de Lumopolis, el Módulo Think Tank está guardado en algún rincón.\nLas miradas indis. se están acercando, lo que podría indicar que los Eclipsites atacarán pronto Lumopolis.",
  str_mission_desc_4004015_long = "Una gran ciud. en el cielo se alzaba a la vista. Parecía que Tu obj., otro Módulo Think Tank, estaba allí.\nTu antiguo enem., Schummer, se había fijado en Lumopolis. Las cosas se veían azules.\nTu prioridad era convencer al Capitán de los Guardianes, Carleen.\nDe repente, su conver. fue interrum. por un ataque sorpresa...",
  str_mission_desc_4004010_long = "Según los habit. de la Baja Lumopolis, fueron atac. por los Eclipsites, casi siempre en la zona este. Los Guardianes fueron a inves. Pero elegiste comprobar el área oeste por instinto de Carleen. El agente plan. en la ciudad susurró en secreto: Tend. la libertad que nos prome. una vez que tengamos en nuestras manos esa cosa.",
  str_mission_desc_4004020_long = "¡Los Eclipsites fueron avistados en el área oeste! Los fugitivos levan. al diablo por todas partes.\nSegún Gertzurde, un líder de escua. de Baja Lumopolis, los ciud. fuera de la ciudad debían ser escoltados.\nParecía que él también fue una vez un famoso caballero...",
  str_mission_desc_4004030_long = "Las coord. propor. por Soroz apuntaban a Jardines de Lumopolis, que estaba fuertem. custodiado en Lumopolis.\nCuando llegó Darkover,\nel Gran Aviduz que acechaba en la osc. se movería para agarrar el Núcleo de Lumopolis.\nAntes de la torm., te diste cuenta de que se aveci. algo grande...",
  str_mission_desc_4004040_long = "El Darkover convirtió a los guardias Lumo en Eclipsites.\nTal cosa no debería estar aquí. ¡La Baja Lumopolis estaba en peligro!\nFuiste bloqueado por los soldados Lumo cuando perseguías a Shire hasta los Jardines de Lumopolis.\nTodo se trataba del Núcleo y el destino de Lumopolis, así que\nVice hizo todo lo posible para convencer a Carleen, la Capitana de los Guardianes de Lumopolis, de que apoyara tu misión.",
  str_mission_desc_4004050_long = "¡Un nuevo avista. desde la zona oeste! ¡Esta vez pare. ser Eclipsites de alto nivel!\nRas. y mátalos a todos.\nCarleen pareció inquieta de nuevo.\nNo importa qué, tienes que seguir adel.",
  str_mission_desc_4004060_long = "Shelt se asoció con su hermana para luchar, pero la balanza aún se inclinaba en tu dirección.\nEl smog ocultó a las hermanas Eclipsites que se dirigían a\n¡La residencia de un Noble de Lumo en Zona Residencial!\n¡Advertencia! ¡Todos los Guardias, regresen a la defensa ahora!",
  str_mission_desc_4004085_long = "En Archivos Lumopolis, Gertzurde está descodificando el Módulo Think Tank.\nShelt le dijo que atraería enemigos a Zona Residencial para ganar tiempo.\nCarleen se dio cuenta de que sería una aventura suicida si escapaban a Zona Residencial;\nAsí que le pidió a Raphaela que buscara en la dirección opuesta mientras localizaba a las hermanas Eclipsites.",
  str_mission_desc_4004100_long = "Mientras tanto, Raphaela no encontró al sosp.\nEn cambio, conoció a Gertzurde, capitán del escua., que acababa de completar su misión.\nSostenía una caja cubierta con tela. ¿Qué contenía?...",
  str_mission_desc_4004110_long = "Siguiendo el rastro de sangre, llegaste a un lugar cerca de Zona Residencial. Las hermanas Eclipsites no tenían otra salida.\nSe volvieron desesperadas en busca de ayuda al hombre misterioso solo para que les dijeran que\nsolo podían elegir entre derrotar a los enemigos y sobrevivir.",
  str_mission_desc_4004120_long = "“Me convertiré en un diente de león... y volaré...\"\nLas mentiras y el poder del hombre miste. trans. a las hermanas en mons. extraños.\nTal poder era una herram. pod. pero un instrumento de tortura inhumano.\nLas hermanas sufridas fueron final. reducidas a cenizas. La molesta crisis se resolvió.\nLa misión de Gertzurde se cumplió. Hasta ahora, Schummer obtuvo el módulo Think Tank completo...",
  str_mission_desc_4005015_long = "Los comandantes de la Legión de Illumina no podían abandonar sus puestos y, por lo tanto, no podían brindar más ayuda.\nTenías que rastrear a Schummer y encontrar la Unidad de Crecimiento Autónoma por tu cuenta.\nPhilyshy, la jefa de inteligencia, trajo una pista ...\nMientras tanto, Carleen solicitó un pedido especial de Lumopolis;\nella perseguiría a Schummer contigo.",
  str_mission_desc_4005010_long = "El número de Colossus caídos indica el núm. de Celestitas sacrificados.\nAhora, final. estabas en la reliquia Colossus de los Sin Nombre 13, pero notaste que est. en ruinas.\nEl director de inves. de Illumina, Gronru, estaba realiz. una investigación aquí.\n¡Era cierto que la Unidad de Crecimiento Autónomo cayó sobre el Colossus!\nNecesitabas el poder de Celestita si querías despegarlo del Colossus.",
  str_mission_desc_4005020_long = "El inte. del Colossus caído sufrió graves daños, por lo que el cam. que condu. a la Unidad de Crecimiento Autónomo estaba lleno de baches y turbu.\nEl inusual temblor anunció la llegada de Schummer.\nElla desató su poder sin restric. y se burló de esos innobles y débiles perdedores.",
  str_mission_desc_4005060_long = "Mentes de los muertos eran tanto un poema como una can., que se entrela. en el vacío y se trans. a través del espacio y el tiempo.\nEl segundo mód. fue el último regalo que te dieron. Ahora, el Colossus comenzó a brillar de nuevo desde su letargo.\nSin embargo, Schummer vino de arriba.\nPara prot. los módulos que tienes, Gronru convocó al trono para cubrir tu retirada.",
  str_mission_desc_4005070_long = "La terminal zumbó.\nEra un mens. de Gronru, que les ordenaba a todos que se retiraran ráp., pero Schummer la interrumpió.\n\"Vuelve al Colossus aban. en 30 minutos y pásame los módulos, o considera a Gronru muerto\".\n¿Tocar la marca o salvar a Gronru?",
  str_mission_desc_4005090_long = "Solo quedan 5 min. antes de la fecha límite.\nSoroz no se fue ni aterrizó. Habías tom. una decisión.\nMientras tanto, Gronru no solo esp. su perdición. Ella era más fuerte de lo que uno podía imaginar.",
  str_mission_desc_4005120_long = "Incluso para los Celestitas, ¿captar el poder de los Eclipsites real. permitió que uno se volv. tan poderoso?\nSchummer ganó esto como un pastel. Pero más allá de nuestras expec., mantuvo la aburrida promesa. Pero ella también dijo que perdonar tu vida era miser. y compasión. Esperándote la próx. vez fuera un combate a muerte.",
  str_mission_desc_4006015_long = "Tenías que encon. el Módulo de Control de Llamas sin un mom. de demora, incluso si no recib. mucho apoyo de Illumina y Lumopolis;\ndecid. dirigirse ustedes mismos al distante Pasillo Susurrante.\nEl Corredor de los Susurros era como un intrincado laberinto, y justo cuando estabas preo., el Señor Sombrío, el Gobernante de Umbraton, te envía un compañero compet.,\nSra. Sheol, quien te guiaría en la explo. de este laberinto...",
  str_mission_desc_4006010_long = "Su oper. de caza salió bien a pesar de que la Sra. Sheol solo apoyaba de forma remota.\nLas huellas de las botas del ejér. se desta. de las huellas de los Eclipsites.\nEra Gertzurde, el traid. que una vez fue un héroe en Lumopolis.\nSe le hizo creer la men. de la muerte de Shelt, por lo que el odio creció en su corazón...",
  str_mission_desc_4006050_long = "Parecías haber encon. el camino correcto hacia el módulo de control de llamas, pero aún no podías bajar la guardia. Gertzurde parecía estar al acecho. ¿Sería esta tu batalla final con él?",
  str_mission_desc_4006060_long = "Gertzurde, que estaba decid. a vengarse de ti, fue derrotada aunque equi. con poder oscuro.\nFinal. supo que la sup. verdad era una mentira que Schummer y el hombre misterioso inven. para controlarlo.\nDesaf., fue muy tarde. Los dientes de león se habían ido con el viento...\nGertzurde estaba tan afligido que decidió llevarte a donde estaba Schummer.",
  str_mission_desc_4006085_long = "Hace una doc. de años, desp. de que term. la crisis de Darkover, Gertzurde fue nom. caballero. No se sentía feliz en su matrim. con la hija de un noble, por lo que su com. de cuento de hadas no tuvo un final feliz, hasta que cono. a Shelt, aunq. fue una elec. equiv.",
  str_mission_desc_4006070_long = "Eclipse sabía de la traición de Gertzurde.\nGuiado por Gertzurde, el Módulo de Control de Llama estaba al alc. de su mano.\nEsperándote en ese mom. estaba tu viejo amigo, Nozard, quien se volvió pode. después de ser trans. por el hombre misterioso.",
  str_mission_desc_4006110_long = "Podías sentir que Schummer estaba al acecho en algún lugar al final.\nTú sabías sobre el iden. de módulo de Gertzurde, ¡pero esto también significa que Schummer probablemente también lo sabía!",
  str_mission_desc_4006120_long = "Charon, que navegó por Other End, hizo que Schummer creyera que eran los refuerzos de Illumina.\nReacios a arries., el hombre misterioso y Schummer se fueron, dejando el cuerpo de Gertzurde.\nCarleen quemó su cuerpo, luego partió con Shelt...\nMientras tanto, Lumopolis se enfrentaba a una crisis aún mayor...",
  str_mission_desc_4007015_long = "El Colossus negro de Schummer llegó sobre el cielo de Lumopolis.\nSin protec. de escudo, la Baja Lumopolis corría un gran peligro. Afort., un Comandante de la Legión de Illumina cercano acudió en su ayuda.\nSchummer pagaría por lo que hizo más tarde, desp. de que esta amenaza inmediata ¡fuera elim!",
  str_mission_desc_4007010_long = "Cada vez más Eclipsites se reunieron en la Baja Lumopolis.\nDada la falta de apoyo de los soldados, todos solo podían actuar por separado.\nSin embargo, nuevamente fuiste conducido a interminables batallas.",
  str_mission_desc_4007050_long = "Gracias a sus tácticas, las operaciones de rescate y eliminaciones en la Baja Lumopolis se llevaron a cabo rápidamente.\nTu conexión con Soroz era muy débil, pero parecía segura.\nJusto cuando todos se sintieron aliviados, Carleen se enteró de que ¡Zona Residencial estaba bajo ataque!",
  str_mission_desc_4007060_long = "El Colossus negro era una amenaza para toda la isla flotante,\npero todos lograron llegar a Zona Residencial a tiempo y derribaron a Mara Sol.\nLa batalla terminó con la arrogancia de Schummer. Sin embargo, en ese momento, escuchó una llamada de ayuda:\n¡¿El propio Colossus estaba siendo atacado?!",
  str_mission_desc_4007085_long = "Intentaste todo para conectarte con Soroz, pero fallaste.\nSin querer adiv. lo peor, la prin. prioridad era volver a apoyar a Soroz de inmediato.\nJusto cuando todos estaban desconcer. porque no había ningún vehículo,\nCarleen voló una aeronave saqueada hacia ti como la salvadora que era.",
  str_mission_desc_4007070_long = "Soroz fue un desastre desp. de la invasión de los Eclipsites.\nSe preveía la peor consec., pero creías que Soroz aún estaba vivo.\n¡Encuentra a Soroz antes de que Schummer te descubra!",
  str_mission_desc_4007100_long = "Final. sentiste a Soroz desp.de la reñida batalla.\nPero ya no era una llamada, sino un mensaje repetido.\n¿Significaba... que Soroz había tenido un mal final?",
  str_mission_desc_4007110_long = "No has podido sentir a Soroz desde hace un tiempo,\ny el dolor punz. en tu corazón es un recor. de la anomalía.\nPor desgracia, Schummer dijo que Soroz ya estaba—",
  str_mission_desc_4007120_long = "Para Soroz, ¡luchaste con Schummer, que se estaba volviendo más fuerte!\n¡El descubrimiento más sorprendente fue que otro Eclipsite de alto nivel, Forsakin, era uno de los compañeros que antes pertenecían a Illumina!\nAntes de que pudieras sorprenderse, cargaron el Colossus negro.\nVivian planeaba arriesgar su vida por tu escape después de un gran impacto que trajo incorporalidad. ¿A qué te enfrentarías ahora...?",
  str_mission_desc_4008015_long = "Un grito te despertó de un sueño extraño.\nEstabas dentro de Aviduz con Vice, que nunca dudó en acudir a tu rescate.\nAhora debes encon. una manera de escapar...",
  str_mission_desc_4008020_long = "\"Nadie se quedará atrás\".\nCon esto en mente, ¡decidiste rescatar a la Jefa Vivian primero!\nMientras tanto, la misteriosa seguía guiándote...",
  str_mission_desc_4008030_long = "A medida que avan., tu cuerpo se sentía extraño.\nSin embargo, no había tiem. para comp. qué pasaba y había que encon. a Vivian lo antes posible.\nMientras tanto, estabas seguro de que Carleen tam. debía estar haciendo todo lo posible para luchar...",
  str_mission_desc_4008060_long = "La anorm. dentro de tu cuerpo no se podía ignorar. Definitivamente, algo estaba a punto de suceder\nporque en la bat., incluso los Eclipsites no te hicieron caso...\n¿Qué estaba pasando en las sombras?",
  str_mission_desc_4008070_long = "Mientras Curie se abría paso, finalmente llegaste al lugar donde estaba retenida la jefa Vivian,\ny donde Solfall, un poderoso enemigo, te esperaba...\nDespués de derrotarlo, la misteriosa mostró su verdadera forma y te ayudó a deshacerte de una materia extraña conocida como la \"semilla\".",
  str_mission_desc_4008085_long = "En Lumopolis, Carleen no recibió el apoyo del Señor.\nSin embargo, esto no frustró su determ. de usar el arma definitiva...\n¡En la sala de control, Carleen había decidido activar a Damocles ella misma!",
  str_mission_desc_4008090_long = "Aunque la Jefa Vivian ha sido resc., no sería prud. escapar ahora mismo.\nEste fue el punto de inflexión de la bat., y el grupo se había conver. en la fuerza clave para paralizar al enem. desde adentro.\nNo podías irte, ¡tenías que dejar de jugar a la def. y al ataq. en su lugar!",
  str_mission_desc_4008100_long = "La bat. se estaba calen. y Schummer final. se dio cuenta de tus acciones.\nParecía que esta feroz bat. estaba dest. a tener lugar en el área central del Colossus Negro: ¡el puente!\nMientras tanto, Damocles también estaba prep. la torm. final...",
  str_mission_desc_4008130_long = "Frente a la codiciada Lumopolis, ¿qué estaría pensando Schummer en este momento?\n¿Estaría su mente llena del pasado, o tal vez de arrepentimiento?\nDebe continuar, ¡la fuente de todo esto está por venir!",
  str_mission_desc_4008140_long = "La batalla final en el puente. Los Eclipsites en su camino fueron elim. rápidamente.\nAl no tener conoc. previo de Damocles, Schummer pronto sintió su poder destruc.:\nCarleen inició el ataque del cañón ligero y, con tu ayuda, penetró en Aviduz.\nEl vend. negro finalmente cayó derrotado...",
  str_mission_desc_4008155_long = "Mientras tanto, mientras la batalla se apagaba—\nVarias figuras clave estab. para dirigir la dirección del mundo se revelaron detrás de escena para tomar el centro del escenario.\nComenzó a formarse un remolino de destino. ¿Cómo navegarías por tu destino final?",
  str_mission_desc_4009015_long = "Después del incidente de Damocles, se dictó un castigo provisional a Carleen, y la importante tarea de averiguar la causa del incidente recayó en ti. Se debe encontrar el \"cuerpo\" de Schummer, y este asunto debe resolverse si deseas reparar Soroz. La casualidad quiso que Aviduz se estrellara en ese lugar familiar pero extraño—Eraveil.",
  str_mission_desc_4009020_long = "El Eraveil que te esperaba era muy diferente al que veías en tu visión.\nEra estéril, sin vida, contaminado con una energía extraña y plagado de enjambres de Eclipsites.",
  str_mission_desc_4009030_long = "Después de que el Colossus se estrellara en Eraveil, se te unieron miembros de Rediesel Wrench en el camino para encontrarlo.\nSinsa y Bopper esperaban rescatar algunos materiales de los restos, pero terminaron separándose de su grupo.",
  str_mission_desc_4009040_long = "Tú y Sinsa se encontraron de nuevo por sorpresa, pero él no parecía saber exactamente dónde se había encontrado.\nSin embargo, no era el momento de ponerse al día. La primera orden del día fue empezar a buscar Aviduz...",
  str_mission_desc_4009050_long = "Aunque la exploración iba mucho más fluida con ayuda de Sinsa, el aire era cada vez más frío.\nLa única explicación era que este lugar se había convertido en un nido de Eclipsites...",
  str_mission_desc_4009070_long = "Encontraste una placa que prueba que uno de los Eclipsites había sido Aurorian.\nParecía que el enemigo destrozado ante ti había sido de hecho una vez como tus compañeros Aurorians.\nDebes acabar con su dolor.",
  str_mission_desc_4009085_long = "Recuperándose de sus graves heridas dentro de su cápsula de curación, Schummer soñó con sí misma hace mucho tiempo.\nLa Schummer del pasado relataba su determinación y deseo con fervor y esperaba su renacimiento.",
  str_mission_desc_4009090_long = "Sentiste dolor y desesperación que envían de lo más profundo de Eraveil. ¿Podría ser esto una ilusión o una realidad? ¿Aviduz también estaba llorando de agonía?",
  str_mission_desc_4009130_long = "Habiendo derrotado a los Eclipsites en Eraveil, finalmente estabas cerca de donde cayó Aviduz. Sin embargo, los miembros del clandestino True Order también parecían tener negocios aquí y estaban reuniendo algo en las sombras.",
  str_mission_desc_4009140_long = "Al encontrarse de nuevo, Forsakin pareció un poco sorprendida de que no te hubieras \"transformado\" todavía.\nAntes de que tuvieras ocasión de ajustar cuentas con ella, se escapó.\nSin embargo, antes de hacerlo, dejó escapar una pista vital, confirmando finalmente que Schummer seguía viva.",
  str_mission_desc_4010015_long = "Mientras tanto, en el Lumopolis Medical Center...\nPhilyshy vino a visitar a Vivian y le informó que estabas persiguiendo a Forsakin.\nLas dos también discutieron brevemente la relación entre Forsakin y el Gran Mariscal.",
  str_mission_desc_4010020_long = "Para continuar tu búsqueda de Forsakin y encontrar a Schummer, ingresaste a Aviduz. Aunque Aviduz se había estrellado hace mucho tiempo, sus restos aún exudaban un poderoso grado de Darkflow. Lo que es aún más desconcertante fue el hecho de que los Eclipsites dentro de él estaban todos corriendo a toda prisa, como si algo terrible estuviera despertando cerca...",
  str_mission_desc_4010030_long = "¡Todavía recuperándose de heridas, Schummer se despertó temprano y se estaba alimentando de Eclipsites para regenerar energía!\nAunque no pudiste hacer cara o cruz de su declive hacia una depravación aún más profunda, ¡debes seguir adelante y encontrar a tu enemigo eterno!",
  str_mission_desc_4010070_long = "Tu enemigo se derrumbó en los brazos de la muerte otra vez.\nLa indiferencia cruel e inmoral de Forsakin te empujó más allá del punto de irritación. ¡Debes encontrarla y a Schummer!\nMientras tanto, en el curso de su búsqueda, salió a la luz más información sobre el pasado de Schummer...",
  str_mission_desc_4010085_long = "Ese día, hace diecisiete años, Schummer se convirtió en el presagio de la caída de Eraveil.\nElla dio grito del caos en nombre de Eclipse. Algunos se vieron obligados a aceptarlo y otros lucharon a muerte en resistencia. Pero al final, los Celestitas estaban condenados. Ella usó su sangre recién derramada para completar su ansiado objetivo—su oscura evolución.",
  str_mission_desc_4010090_long = "Después de echar un vistazo al pasado de Schummer, vio que su sueño de Eraveil reflejaba la tragedia de ese recuerdo lejano.\n El camino de la venganza había durado bastante. Es hora de encontrar a Schummer y poner fin a todo.",
  str_mission_desc_4010130_long = "Forsakin finalmente empujó a Schummer más allá del punto de retorno, lo que la obligó a experimentar un gran avance en el poder—\nSin embargo, perdió todo el control como resultado. En un estado de absoluta locura, apareció ante ti una vez más.\nSolo uno de ustedes saldría vivo de esta batalla.",
  str_mission_desc_4010140_long = "Derrotaste a la enloquecida Schummer, pero parecía haber un flujo interminable de poder dentro de ella.\nPara recuperar la Semilla, Forsakin le quitó su poder. Schummer, que vivió únicamente para su propia cruzada retorcida por la justicia y el renacimiento, finalmente murió en medio de una marea de Eclipsites—\nComo hizo su propia gente, hace muchos años.",
  str_mission_desc_4010155_long = "Con la ayuda de Rediesel Wrench, todos lograron escapar ilesos de Aviduz y dejaron Eraveil.\nTambién lograste conectar con éxito el módulo Think Tank obtenido de Schummer con Soroz y las reparaciones parecían prometedoras hasta ahora.\nAhora, no podías evitar preguntarte a dónde te llevaría tu próxima aventura.",
  str_mission_desc_4101015_long = "Soroz se volvió inestable sin la plantilla de eco. Si esto duraba más tiempo, el daño podría sobrevenir. Vice y tú decidisteis visitar Entrañas ubicada en la frontera de la tierra de la Noche Eterna siguiendo el ejemplo proporcionado por el módulo Think Tank.",
  str_mission_desc_4101020_long = "Al llegar a Entrañas 80 en la frontera de la tierra de la Noche Eterna, te diste cuenta de que los Eclipsites habían reclamado este lugar como suyo desde el abandono de Illumina. El intenso Darkflow hizo casi imposible usar Luminatics. Bajo estas circunstancias, inicias la investigación con cautela.",
  str_mission_desc_4101030_long = "Vice y tú avanzaron más profundamente en Entrañas. Las huellas de la guerra se podían ver por todas partes bajo una gruesa capa de polvo acumulada durante largos años. En las ruinas, descubriste algunos módulos Colossus desechados...",
  str_mission_desc_4101040_long = "La pieza que podría usarse para reparar la plantilla de eco de Soroz estaba incrustada en una máquina en la cámara central. Luchaste para quitártelo, lo que provocó que el núcleo de energía de esta Entrañas se detuviera. Sin energía, Entrañas comenzó a derrumbarse y un eclipse de alto nivel surgió durante el colapso.",
  str_mission_desc_4101055_long = "Usted y Vice se enfrentaron al Eclipsite de alto nivel con las cargas adicionales que trae el Darkflow mientras buscaban la oportunidad de escapar. Sin embargo, el Eclipsite se abrió camino por completo. En este momento crucial, Reinhardt vino a rescatarte. Para su sorpresa, ese High-Level Eclipsite parecía ser un viejo camarada suyo.",
  str_mission_desc_4101060_long = "Reinhardt te llevó a una ruta de escape diferente hacia el suelo. Pero el Darkflow se hizo más pesado a medida que ascendías, ya era después del anochecer. La batalla solo se volvería más difícil a partir de ahí.",
  str_mission_desc_4101070_long = "Bajo su continuo cuestionamiento, Reinhardt comenzó a contar una historia del pasado. Una vez, sus camaradas libraron una ardua batalla con ella en Entrañas 80. Escapó del cerco enemigo para buscar ayuda, pero solo para descubrir que Illumina los había dejado atrás para salvar a la mayoría de la población.",
  str_mission_desc_4101080_long = "Llegaste al nivel del suelo en la oscuridad más profunda justo antes del amanecer. Forsakin y el Eclipsite de alto nivel esperaban en silencio. Reinhardt te pidió ayuda. Quería hacer un último intento para traer de vuelta a su antiguo camarada.",
  str_mission_desc_4101090_long = "Forsakin despertó el odio profundamente enterrado del High-Level Eclipsite y cambió su apariencia. Una batalla mortal era inminente. Reinhardt sufrió heridas graves para protegerte. En esta situación desesperada, ella opuso una valiente resistencia...",
  str_mission_desc_4101105_long = "Amenazados por el ejército de Eclipsite, Vice y tú trajisteis a Reinhardt gravemente herido de vuelta a Soroz y os dirigisteis hacia el salvavidas de Illumina. En el camino, Reinhardt recordó algo del pasado. Algunos cambios de gran importancia parecían estar gestándose dentro de la sólida Ciudad Subterránea de Illumina...",
  str_mission_desc_4201015_long = "Siguiendo las pistas que logró obtener, partió hacia Eraveil en busca de la Base de mantenimiento Colossus con la esperanza de encontrar una manera de devolver a Soroz a su estado original. Sin embargo, las cosas no salen exactamente como estaban planeadas...",
  str_mission_desc_4201020_long = "De camino a Eraveil, Soroz es atacado por Eclipsites en lo que parece ser una emboscada planeada. Durante la batalla, el ataque de Eclipsites destruye el panel de control del Colossus y Soroz comienza a caer...",
  str_mission_desc_4201040_long = "Aterrizas en un vasto espacio en la base de una torre blanca. Según los datos de Soroz, esta es la \"Asfalto\", así que la base que estás buscando debería estar cerca. Es hora de agarrar el detector de metales y comenzar a explorar.",
  str_mission_desc_4201050_long = "A medida que comienza a buscar, algunos eclipses que lo siguen rodean silenciosamente la Torre Blanca. Para continuar la búsqueda, vuelas la entrada a la pista con Barton's ayudar y evitar que lleguen más lejos.",
  str_mission_desc_4201060_long = "Siguiendo la entrada que descubriste, ingresas a una gran base debajo de Eraveil, y te encuentras con muchos rastros de Caelestites que habían vivido aquí antes, que nunca supiste que existían.",
  str_mission_desc_4201070_long = "Después de una feroz batalla, caíste inconsciente por la falta de oxígeno. Por pura casualidad, te conectaste con la IA que controla la base. Con su ayuda, se encendió la ventilación y recobró el conocimiento. Bajo la guía de la IA, continúas explorando la base...",
  str_mission_desc_4201090_long = "Llegas a un gran espacio en la base, y hay señales de que esta área alguna vez fue conocida como la Zona del Exilio, y que los exiliados aquí en el pasado eran Caelestites. Aquí, encuentras un Lance Rifle que una vez perteneció a Caelestite y lo usas con éxito para derrotar a Eclipsites.",
  str_mission_desc_4201100_long = "Perseguido por un poderoso Eclipsite, no te queda más remedio que usar los dispositivos defensivos de la base subterránea para lidiar con él. Pero estos dispositivos no son solo para atacar Eclipsites, también son peligrosos para los Aurorianos. Vice también resulta herido y cae en un extraño estado de inconsciencia conocido como \"hibernación\".",
  str_mission_desc_4201115_long = "Con el fin de encontrar una cura para Vice y reparas a Soroz, continúas tu exploración del núcleo de la base. Allí, te encuentras con una extraña máquina, Circular System, una que solo tú, un Caelestite, puedes usar. Desde esta máquina, puedes vislumbrar algunos secretos desconocidos.",
  str_mission_desc_4201120_long = "Te las arreglas para encontrar un registro de un Aurorian despertando de la hibernación en el Sistema Circular. Pero debido a la edad, solo puede acceder a fragmentos de información. Decides explorar las profundidades para encontrar más pistas.",
  str_mission_desc_4201140_long = "Cuando el sistema de la base comienza a reiniciarse repentinamente, pierdes el control de la base y te conviertes en el objetivo de su ataque. Los Guardianes de la base han despertado de un sueño profundo y debes derrotarlos para recuperar el control de la base.",
  str_mission_desc_4201155_long = "A medida que recupera el control de la base, el reinicio se completa y le brinda acceso completo. En medio de estruendosos temblores, la torre comienza a elevarse, revelando lentamente su forma original. Las creaciones de tecnologías antiguas en todo Astra comienzan a resonar extrañamente...",
  str_mission_desc_4202015_long = "Al obtener acceso administrativo al Obelisco del Retorno, se entera de un dispositivo llamado \"Chord Link\" que puede salvar a Vice. Sin embargo, como el Obelisco del Retorno se ha deteriorado, no hay información sobre este dispositivo en el sistema, por lo que tendrás que ir al área donde se encuentra para investigar más a fondo.",
  str_mission_desc_4202020_long = "Mientras buscas el Chord Link, Barton sigue el rastro de Forsakin hacia la torre. Sin embargo, se ha perdido en el vasto Obelisco del Retorno...",
  str_mission_desc_4202040_long = "A raíz de Bartonla persecución, Forsakin abandona su plan de seguirte y recurre a la fuerza. Tienes que ganar tiempo para descifrar el Control de acceso de la Zona de acordes bajo Forsakinataque de",
  str_mission_desc_4202050_long = "Huyes a la Zona de Acordes para evitar Forsakin, pero el acto de descifrar el control de acceso activa las defensas de Chord Zone. Con todas las trampas en el pasadizo activadas, te enfrentas a un obstáculo desafiante. Justo cuando las cosas llegan a un punto crítico, desencadenas una explosión trampa, deteniendo brevemente Forsakin y entrando en la Zona de Acordes.",
  str_mission_desc_4202060_long = "Con el fin de proteger Vice y derrota Forsakin, Barton, que está gravemente herido, decide transformarse con el Chord Link. Durante este tiempo, Forsakin ordena a Eclipsites que rompa la puerta. Comprar Barton tiempo, te enfrentas contra Forsakin.",
  str_mission_desc_4202070_long = "Como Barton completa la sincronización, obtiene nuevos poderes y sale del Chord Link para unirse a ti en la lucha Forsakin. A medida que la marea cambió, Forsakin huye en el caos con Barton siguiendo muy de cerca...",
  str_mission_desc_4202085_long = "El éxito de Barton te lo asegura, y pones Vice en el Chord Link para sincronización. A través de la vigilancia del Obelisco del Retorno, ves Eclipsites reuniendo un gran ejército fuera de la torre y Aurorianos de todos lados luchando duro. Mientras eres testigo de esto, decides expulsar a estos Eclipsites de Eraveil con tus propias manos.",
  str_mission_desc_4202090_long = "Ya que será un tiempo antes Vice despierta, tu y Carleen no tienen más remedio que dejarla en el Chord Link para perseguirla. Forsakin fuera de la torre. En este momento, la escena fuera de la torre es de terror, con un número abrumador de Eclipsitas y Aurorianos luchando duro. Es como si el tiempo hubiera retrocedido al día en que Eraveil fue atacado hace diecisiete años...",
  str_mission_desc_4202100_long = "Bajo los implacables ataques de Eclipsites, todos se mantienen firmes, haciendo todo lo posible para resistir. Luego, el Eclipse revela su carta de triunfo: los cañones Darkflow. Estas armas inesperadas te colocan inmediatamente en desventaja. La esperanza de victoria parece desvanecerse rápidamente...",
  str_mission_desc_4202115_long = "Como todos los que están fuera del Obelisco del Retorno siguen enfrascados en la batalla, para cambiar el rumbo, Reinhardt sugiere dejar algunos atrás como una distracción mientras ella y tú emboscan a los Eclipsites. Para proteger a Eraveil, decides unirte a Reinhardt.",
  str_mission_desc_4202130_long = "Con Reinhardt y Forsakin enfrascados en la batalla, la marea aún no ha cambiado. Al sentir una crisis inminente, decides regresar al Obelisco del Retorno y obtener acceso al Anillo central para activar el arma definitiva del Obelisco del Retorno: el Acorde de la Ley.",
  str_mission_desc_4202140_long = "Para obtener acceso al Core Ring, te enfrentas solo a los Guardianes, pero no puedes derrotarlos. Justo cuando estás a punto de ser derrotado, Vice, que acaba de recuperarse de la hibernación, llega a tu lado con sus nuevos poderes. Ustedes dos trabajan de la mano para derrotar a los Guardianes y finalmente activar el Acorde de la Ley.",
  str_mission_desc_4202155_long = "El \"regalo\" que te dejó el Maestro Francis te permite activar con éxito el Acorde de la Ley, manteniendo todos los Eclipsites alejados del Obelisco del Retorno y poniendo fin a la batalla. Al no poder volver a activarse por falta de energía, el Obelisco del Retorno se convierte en un monumento a la historia, y todos se preguntan qué pasará con él...",
  str_mission_desc_4203015_long = "El cuerpo de Vice de repente comenzó a emitir una luz extraña, un posible efecto secundario del uso de Chord Link. Preocupado por la situación, contacta a Vivian con la esperanza de que pueda identificar el origen del problema.",
  str_mission_desc_4203020_long = "Preocupado por la seguridad de Vice, acepta ayudar a un equipo de investigadores de Illumina a investigar las nuevas funciones de Soroz. Durante la investigación, los investigadores descubren una gran cantidad de datos de combate antiguos; ahora desean que acceda a estos datos utilizando el Simulador de batalla de Illumina y realice más investigaciones al respecto.",
  str_mission_desc_4203030_long = "Realiza una serie de pruebas con el Simulador de batalla, un dispositivo sofisticado que se utiliza para crear escenarios de combate casi perfectos. Después de ver el simulador en acción, Reinhardt cree que al producir batallas aún más complejas, este dispositivo puede usarse incluso con fines de entrenamiento.",
  str_mission_desc_4203040_long = "Entras en el Simulador de Batalla una vez más, pero el entorno interior se ha convertido en una Zona Oscura. Dentro de esta simulación oscura y hostil, tu objetivo es derrotar a los Eclipsites y romper su cerco.",
  str_mission_desc_4203050_long = "Usando el terreno para obtener una pequeña ventaja, finalmente derrotas al último de los eclipses simulados. Maltratados y magullados, tú y tus aliados emergen del Simulador de batalla después de una victoria reñida y encuentran a Reinhardt hablando con los otros investigadores. Escuchas parte de su conversación y descubres que Reinhardt vivió personalmente la batalla que acabas de experimentar...",
  str_mission_desc_4203060_long = "Regresas al simulador y el entorno se ha alterado drásticamente una vez más. Los Aurorianos en la simulación usan armas que nunca antes habías visto y se están defendiendo desesperadamente de oleada tras oleada de Eclipsites sedientos de sangre. A medida que caen ante los monstruos uno por uno, el mundo virtual parece volverse cada vez más desesperado...",
  str_mission_desc_4203070_long = "Dentro de la batalla simulada, las tragedias de una guerra apocalíptica asaltan todos tus sentidos. Soldados desesperados, Eclipsites arrasadores y un monstruo demoníaco como nunca has visto rodeándote... De repente, ocurre un error en el simulador, y justo cuando estás a punto de caer ante el feroz ataque de Jormungand, Soroz inserta su conciencia en la batalla y logra sacarte. Cuando recuperas tus sentidos, te sorprendes al darte cuenta...",
  str_mission_desc_4203085_long = "El Consejo de Ciencias, una organización que guarda los secretos mejor guardados de la Federación Illumina, los ha invitado personalmente a usted y a Reinhardt para reunirme con ellos. Cualesquiera que sean sus motivos, son los más capaces de comprender la condición de Soroz en este momento. Al entrar en la sala de conferencias, se apodera de usted una sensación de inquietud que se avecina. De repente, Reinhardt suavemente coloca su mano sobre tu hombro, rompiendo la tensión opresiva que se cierne sobre la habitación.",
  str_mission_desc_4203090_long = "Al final de la reunión, usted y Algol llegan a una especie de acuerdo. A petición suya, inicia un enlace mental con Guardian One, una máquina antigua en posesión de la Federación Illumina. Hacerlo beneficiará a ambas partes: los investigadores de Illumina tendrán la oportunidad de observar las interacciones de Caelestite con un dispositivo antiguo, y usted tendrá la oportunidad de pedirle ayuda a Guardian One.",
  str_mission_desc_4203100_long = "En el proceso de establecer un vínculo mental con Guardian One, te das cuenta de que, a pesar de existir durante incontables años, esta inteligencia artificial tiene la personalidad de un simple niño; como tal, solo confiará en aquellos que interactúen con él con honestidad y equidad. Después de sentir tu preocupación por Soroz, Guardian One inmediatamente decide ayudarte a rescatar la conciencia de Soroz.",
  str_mission_desc_4203110_long = "Guardian One te lleva al campo de batalla simulado en el que se encuentra Soroz. Las secuelas de una antigua catástrofe de eones pasados se encuentran ante ti, una en la que los eclipses aún vagan por el planeta sin vida. Sabiendo que la simulación está llegando a su fin, debes buscar a tu querido compañero entre las ruinas de un mundo moribundo antes de que todo se derrumbe.",
  str_mission_desc_4203120_long = "En los escombros de un mundo destrozado, finalmente encuentras a Soroz y accedes a su base de datos. Familiarizado con las cosas que te rodean, pero inseguro del tiempo o el lugar en el que existen, tu estupor finalmente se rompe cuando Guardian One te dice que ha descubierto una serie de registros antiguos dentro de la terminal. Aquí, los Caelestites están lejos de casa, vagando sin rumbo...",
  str_mission_desc_4203130_long = "Guardian One le dice que para reparar Soroz, primero debe ingresar a sus memorias y solucionar los errores en sus datos. Con la ayuda de Guardian One, debería ser una tarea bastante simple. Mientras ingresa a los recuerdos de Soroz, ve más y más registros de la terminal. En ellos, los Caelestitas parecen estar disminuyendo en número...",
  str_mission_desc_4203140_long = "Con la ayuda de Guardian One, elimina con éxito los errores en la base de datos de Soroz. Con su mente todavía en los registros de la terminal, decide acceder a ellos una vez más. Dentro de los registros, eres testigo de un milagro: bajo el cuidado de los Caelestitas, los Colosos nacen y reciben sensibilidad. Después de este breve milagro viene una larga espera, un período de tiempo tan largo y sin incidentes que requiere cada onza de tu concentración para llegar al final. De repente, una escena familiar se desarrolla ante ti: Eraveil.",
  str_mission_desc_4203155_long = "Después de salir del mundo virtual, regresa a la sala de conferencias una vez más. El Consejo de Ciencias ha comenzado a discutir los eventos que acaban de presenciar. Creen que Soroz está operativo una vez más, pero concluyeron que la sensibilidad del Coloso no fue más que el resultado de un accidente. Para restaurar verdaderamente la conciencia de Soroz, debes viajar a un lugar aún más lejano...",
  str_mission_desc_4204015_long = "Encargado del Cyborg de Combate Frágil del Consejo de Ciencias, su próxima tarea es ponerse en contacto con las tropas de Illumina estacionadas en la ciudad de Twilight. Allí, debes intercambiar el droide por los recursos necesarios para restaurar la conciencia de Soroz. Nunca has oído hablar de esta ciudad, que está situada en el frente de Illumina; para su sorpresa, encuentra a Carleen allí en una misión externa.",
  str_mission_desc_4204020_long = "El pueblo de Crepúsculo, ubicado cerca de las Ruinas de Aurora y bordeando la zona de la Noche Eterna, es un crisol de diferentes facciones militares. Los Lumo Knights estacionados aquí ya se han puesto en contacto con Carleen; parece que Beretta y Yingel tienen dos interpretaciones muy diferentes de este lugar remoto y aislado. Cuando los Eclipsites comienzan su asalto, el objeto frágil en tu mano comienza a emitir un sonido extraño...",
  str_mission_desc_4204030_long = "Un sonido extraño lo despierta de su sueño, y Sean casi \"elimina\" a Soroz. Resulta que Sean se apresuró desde Twilight después de recibir un mensaje sobre tu llegada hace algún tiempo. Su plan era darte la bienvenida mientras realizaba su trabajo habitual de \"eliminación\", que incluye limpiar Eclipsites del área alrededor de Twilight, así como cualquier otro invasor sospechoso. Para un oficial de base como Sean, esta es solo una práctica común.",
  str_mission_desc_4204040_long = "Cuando Axelia, Yingel, y Sean se saludan, te das cuenta de que los tres tienen una historia común. Explican que son \"graduados\" del Programa Phospherus, un programa encabezado por el Consejo de Ciencias con el propósito de convertir a los niños en súper soldados. Aunque los tres han crecido mucho desde entonces, todavía bromean y se ríen entre ellos como lo hacían cuando eran niños.",
  str_mission_desc_4204050_long = "A pesar del salvaje conflicto que rodea a Crepúsculo, sus residentes están más preocupados por refugiarse de un desastre natural inminente. La aurora amenaza con salirse de control y todos buscan desesperadamente refugio para capear la inminente tormenta de energía. Los Eclipsites se aprovechan del pánico generalizado y comienzan a atacar indiscriminadamente. Justo cuando decides entrar en la refriega y salvar a la gente del pueblo, descubres que ya han llegado refuerzos en forma de un regimiento de soldados de Lumopolis: los Ironthorn Knights.",
  str_mission_desc_4204060_long = "Ante probabilidades aparentemente insuperables, los Ironthorn Knights rompen fácilmente las filas de los Eclipsites antes de atacarlos. Después de ver la increíble destreza de combate de Leo en acción, decides ayudar a los caballeros a defenderse de los Eclipsites restantes. Sin embargo, justo cuando las mareas parecen cambiar a tu favor, surge una amenaza nueva e incluso más cruel...",
  str_mission_desc_4204070_long = "Una nueva ola de Eclipsites ingresa al campo de batalla, y los Lumo Knights no pueden defenderse de sus ataques mientras protegen a la gente del pueblo. Te separas del frente para defenderlos, pero los Eclipsites son implacables en su asalto. Justo cuando llegas a tus límites, una joven aparece de repente en medio de la batalla; con una luz sagrada cegadora, instantáneamente disipa cada Eclipsite en las inmediaciones. Con la gente del pueblo a salvo, vuelves a unirte a la lucha sin dudarlo y finalmente reclamas la victoria. Después, la misteriosa chica conocida como Joselyne te invita a cenar con ella en Crepúsculo.",
  str_mission_desc_4204085_long = "Joselyne te lleva a un restaurante en Crepúsculo y te cuenta más sobre la ciudad: su historia, sus problemas y, lo que es más importante, sus lazos con un Coloso antiguo y perdido. Después de terminar su comida, regresa con Illumina Researcher, quien lo ayuda a restaurar completamente la conciencia de Soroz, aunque solo sea temporalmente. En esos breves momentos, Soroz te indica un lugar determinado: una Ciudad Subterránea en lo profundo de la Zona Oscura, donde el antiguo Coloso yace inactivo...",
  str_mission_desc_4204090_long = "Decides viajar al lugar que mencionó Soroz y recibes el apoyo de Illumina y Lumopolis, así como de la recién conocida Joselyne. Después de ver su impresionante poder en el campo de batalla, la amenaza de los Eclipsites parece mucho menos desalentadora que antes.",
  str_mission_desc_4204115_long = "Tú y tus aliados os adentráis más en las ruinas. Desconfiado de la gran cantidad de Eclipsites que deambulan por el área, su grupo procede con la máxima precaución. En este momento, sin embargo, Sean decide desafiar a Axelia a un concurso de fuerza: el que derrote a la mayor cantidad de Eclipsitas es el ganador y el más fuerte de los dos.",
  str_mission_desc_4204120_long = "Finalmente llegas al Puente del Coloso y comienzas la búsqueda del módulo necesario. Sin embargo, al encontrarlo, descubres que el módulo hace mucho tiempo que se fusionó con el Coloso; quitarlo por la fuerza solo causaría más daño. Luego, Axelia interviene y le proporciona un dispositivo que puede copiar los datos del módulo, pero dice que llevará algún tiempo...",
  str_mission_desc_4204130_long = "Después de defenderse de los Eclipsites atacantes, el dispositivo de Axelia finalmente termina de copiar los datos del módulo. Justo cuando tu grupo decide evacuar, el Coloso comienza a retumbar violentamente; ¿Está a punto de salirse de control? Para pacificar al Coloso y proteger los asentamientos cercanos a las ruinas, decides iniciar un Enlace Mental con el Coloso...",
  str_mission_desc_4204140_long = "Parece que el estruendo no fue causado por el Coloso... Entonces, ¿cuál fue el responsable? Después de establecer un vínculo mental con el Coloso, descubres que una gran cantidad de eclipses se han reunido fuera de él; dentro de sus filas, sientes la presencia de una entidad extremadamente poderosa...",
  str_mission_desc_4204155_long = "Regresas a Crepúsculo con Axelia y los demás y te despides. Con sus valiosos datos finalmente en la mano, viaja de regreso a Illumina. Solo el tiempo dirá si estos datos realmente ayudarán a restaurar a Soroz; todo lo que puedes hacer es esperar. Es en ese momento cuando recibes una invitación de los altos mandos de Illumina, una solicitud para viajar a Entrañas oculta donde existe otro Chord Link...",
  str_mission_desc_4205015_long = "Tenencia Vice como rehén, Forsakin te está obligando a ir con ella, aparentemente después de que Illumina descubriera en secreto un Chord Link, con la intención de completar los datos del experimento a través de Vice.\nEn otro frente, la batalla en Crepúsculo se ha intensificado a medida que Leo envía señales de socorro tanto a Lumopolis como a Illumina.",
  str_mission_desc_4205020_long = "Para completar el experimento, Forsakin te obliga a luchar contra los soldados de Illumina y retrasarlos. Solo espero que cumpla su promesa de no matar a nadie.",
  str_mission_desc_4205030_long = "¡Has llegado al destino, donde Forsakin, que está familiarizada con los alrededores, llamó al Instituto X que ella construyó! Antes de que puedas reflexionar más, ella quiere Vice para iniciar el Chord Link! Que es lo que va a pasar?",
  str_mission_desc_4205040_long = "Forsakin no está satisfecho con el resultado de la operación de Chord Link. Usted y Vice intenta tenderle una emboscada, solo para que ella convoque a una multitud de Eclipsites para oponerse a ti.",
  str_mission_desc_4205041_long = "—",
  str_mission_desc_4205050_long = "No eres rival para Forsakin y luchaste en vano. Helios aparece junto a Forsakin y te aísla de Vice, obligándolos a ambos a obedecer.\nMientras tanto, Ulises llama Yingel en una reunión secreta y le encarga una misión especial.",
  str_mission_desc_4205065_long = "En el Crepúsculo asediado, Leo no recibe ayuda, sino una invitación a un Ejercicio Militar Conjunto, que aprovecha como una oportunidad para alertar al mundo de la amenaza de la Zona Oscura.\nMientras tanto, Illumina y Lumopolis también comienzan a prepararse para el ejercicio, como si la mente maestra detrás de él prometiera verlo hasta el final...",
  str_mission_desc_4205070_long = "Después de que Forsakin te separó a ti y Vice, no tienes ningún medio para contactarla más que un comunicador. Continúa mientras Forsakin comienza a buscar en los archivos información sobre el programa Phospherus.\nMientras tanto, Yingel se reúne con el oficial de inteligencia Anatoli con una orden secreta, parece que su objetivo es el Instituto X también.",
  str_mission_desc_4205080_long = "Para encontrar el perdido usted y Vice, así como descubrir qué hay realmente detrás del ejercicio conjunto, Carleen llega a Illumina para hablar con Gronru, quien le indica el Instituto X, donde se encuentra Yingel por casualidad y se entera de la crisis aquí.",
  str_mission_desc_4205090_long = "Forsakin intenta obtener más información sobre el programa Phospherus, pero accidentalmente activa las defensas. Después de derrotarlos, cambia las palabras clave y accede con éxito a los archivos.",
  str_mission_desc_4205100_long = "Pierdes el contacto con Vice cuando el comunicador se queda sin energía, no sin antes dar Yingel y otros tiempo para averiguar la ubicación exacta de Vice.\nSin embargo, cuando Yingel se acerca, se da cuenta de que un poderoso enemigo la está protegiendo Vice—Helios.",
  str_mission_desc_4205101_long = "—",
  str_mission_desc_4205110_long = "Yingel y Helios están enfrascados en una lucha feroz. También se da cuenta de que Forsakin probablemente sentirá la batalla.\nMientras tanto, Carleen te alcanza Ella trata de derrotar a Forsakin y sacarte de aquí, solo para verse envuelta en una batalla cuesta arriba por su cuenta.\nLa visión desesperada de Helios haciendo equipo con las indicaciones de Forsakin Yingel para incinerar audazmente el Chord Link...",
  str_mission_desc_4205120_long = "El llamado infierno resulta ser una mera ilusión por Yingel, pero cambia el rumbo de la batalla y le da ventaja a tu bando. Yingel también trata de convencer a Forsakin de que Reinhardt nunca la abandonó después del incendio del laboratorio y que su supuesta venganza fue equivocada desde el principio.",
  str_mission_desc_4205130_long = "Negándose a rendirse, Forsakin corta la energía del laboratorio y sella la puerta, ganando tiempo para ella y el Chord Link para mejorar aún más a Helios.\nMientras tanto, el motivo de Ulysses está saliendo a la luz lentamente, ya que se interesa mucho en el resultado del experimento de Forsakin...",
  str_mission_desc_4205140_long = "Finalmente, Forsakin fusiona tres mejoras diferentes en Helios, alterando drásticamente su apariencia. Después de que termina la batalla, Helios sorprendentemente recupera sus sentidos, aunque con una memoria algo fragmentada.\nMientras tanto, Wrath y Reinhardt llega para enfrentarse a Forsakin, pero aún así logra escapar.",
  str_mission_desc_4205155_long = "Nadie puede encontrar a Forsakin en el Instituto X y se especula que podría estar escondida cerca de Gannon. Mientras tanto, el Ejercicio Militar Conjunto comienza según lo planeado en esa ciudad, ya que los representantes de varios poderes se reúnen y luchan por el título del mejor ejército.\nPero a la sombra de Gannon, Forsakin y Helios acechan...",
  str_mission_desc_4206015_long = "El ejercicio comienza, atrayendo a los equipos de Gannon de Lumopolis, Illumina y Twilight, así como a tu trío y otro escuadrón misterioso.\nVivian le informa de las reglas e indica que el vencedor tendrá el honor de desafiar al Gran Mariscal.\nMientras tanto, en la esquina de la ciudad, Forsakin espera a los miembros de Eclipse para rescatarla a ella y a Helios.",
  str_mission_desc_4206020_long = "Primero está el familiar Simulador de batalla para que todos revivan arduas campañas del pasado. Muchos sufren la derrota contra viento y marea, excepto el escuadrón de Leo de Crepúsculo, que obtiene una victoria milagrosa.",
  str_mission_desc_4206030_long = "La siguiente es la parte del salón de clases, en la que se pueden intercambiar créditos de curso en función de las calificaciones y el rendimiento por suministros. Así, bajo la tutela de Wrath, todos se adentran en el fino arte de la \"pelea\"...",
  str_mission_desc_4206040_long = "Un entrenamiento supuestamente inofensivo es saboteado y casi acaba en desastre. Supongo que la competencia entre escuadrones no es tan amistosa, después de todo.\nMientras tanto, dado Leo y el desempeño sobresaliente de Yingel, decide solicitar sesiones adicionales de simulador, pero alguien manipula eso también...",
  str_mission_desc_4206041_long = "—",
  str_mission_desc_4206050_long = "Para los eclipses que salen de la nada en Gannon, Leo y Zhao van por encima de su autoridad para ordenar a los soldados de Illumina que lleguen a una resolución. Wrath no está muy interesado después de enterarse, pero llega a apreciar el talento de Leo.\nEn una conversación, Wrath también se entera de la desesperación en Crepúsculo y se da cuenta de que los altos mandos parecen estar censurando las noticias...",
  str_mission_desc_4206060_long = "Las lecciones avanzan hacia el combate real en el Ejercicio Militar Conjunto. Bajo tu consejo, todos derrotan a todos los adversarios a través de una alianza temporal, llevando el evento al segmento final: Capture the Flag.\nTodo el mundo comienza a gastar los créditos del curso ganados en equipo y accesorios en previsión de la gran batalla para capturar la bandera en Entrañas.",
  str_mission_desc_4206070_long = "Yendo a Entrañas en busca de la bandera, tú, Carleen, y Vice están planeando una estrategia cuando ese misterioso escuadrón de Umbraton se encuentra con una banda de Eclipsites a cuestas...",
  str_mission_desc_4206080_long = "Finalmente pones fin a los Eclipsites después de una batalla caótica, pero el escuadrón Umbraton que inició el problema se niega a entrar en Entrañas contigo, como si tuvieran su propia misión.\nMientras tanto, los dos escuadrones más fuertes, Team Leo y equipo Yingel, empezar a luchar entre sí en algún lugar.",
  str_mission_desc_4206090_long = "Con el misterioso escuadrón aparentemente manipulando tu ruta, te encuentras con un peligroso monstruo araña.\nDespués de una dura batalla, corres hacia donde está la bandera solo para encontrar la pelea entre Team Leo y equipo Yingel terminado, siendo el ganador—Equipo Yingel.",
  str_mission_desc_4206105_long = "Equipo Leo está muy contento con ser el subcampeón ya que lo hicieron como un favor a cambio de que Illumina enviara refuerzos a Twilight.\nMientras tanto, Ulysses avanza en el plan para lograr su objetivo a través de las acciones de Forsakin en Gannon.\nDe hecho, en el sitio para luchar contra el Gran Mariscal, Yingel recibe noticias de una invasión de Eclipsite en la ciudad. Tú, Leo, y otros deciden ayudarla en el asunto.",
  str_mission_desc_4206110_long = "En el enfrentamiento contra el Gran Mariscal, Axelia muestra un nivel inusual de poder y un deseo de muerte. Reinhardt también siente algo extraño en el partido de exhibición.\nMientras tanto, el desvío de Eclipsites despeja a Forsakin y Helios para escapar de Gannon a través de un pasaje secreto.",
  str_mission_desc_4206120_long = "Los eclipses en Gannon parecen estar atrayendo tu atención a propósito, pero tampoco puedes interrumpirlos y dejar que se vuelvan locos. Mientras tanto, también sientes la presencia de Figerald the Wraith.\nEn la arena, la ofensa casi suicida de Axelia está empezando a preocupar. Reinhardt.",
  str_mission_desc_4206121_long = "—",
  str_mission_desc_4206130_long = "Reinhardt concede sólo para detener Axelia de sus propios ataques suicidas, pero eso también cae dentro del plan de Ulises.\nTú, Leo, Yingel ¡y otros se apresuran a ir a la ubicación de Wraith, donde se guarda la computadora central de Guardian One!\nMientras tanto, Forsakin y Helios llegan al lugar de encuentro solo para descubrir que Esien ya ha enviado soldados allí. Se dan cuenta de que Eclipse los ha tendido una trampa.",
  str_mission_desc_4206140_long = "Relegado a un mero peón de sacrificio por el Eclipse, Figerald es completamente derrotado y detenido. Pero otro Wraith desconocido ha tomado el núcleo de Guardian One y no hay nada que nadie pueda hacer al respecto.\nEn cuanto a Forsakin, sale limpia cuando Helios se queda atrás para cubrir la huida.\nDe vuelta en la arena, Ulysses revela que el Comité ha encontrado evidencia de Reinhardt albergando a Forsakin en su residencia, poniendo al Gran Mariscal bajo arresto frente a todos.",
  str_mission_desc_4206155_long = "Y aquí es donde están las cosas. Incluso si encuentras Reinhardt Ser retirado del servicio es una píldora difícil de tragar, sigue siendo un hecho.\nEn cuanto a Ulysses, está muy contento con interceptar los resultados del experimento de Forsakin, pero Wraith aprovecha la oportunidad de robar Guardian One y estropea la operación.\nque va a pasar con Reinhardt? ¿Y qué enemigos desconocidos yacen en la sombra?",
  str_mission_desc_4207015_long = "La Federación Illumina está llevando a cabo su tercer juicio público a Reinhardt por cargos de traición. Mientras tú y Vice esperan fuera de la sala de interrogatorio, finalmente les llega la noticia de que a Reinhardt le han despojado de su título de Gran Mariscal y ha sido condenada a prisión. La noticia los deja a ambos preguntándose sobre la posibilidad de un trastorno monumental en el horizonte.",
  str_mission_desc_4207020_long = "Mientras se encuentran desconcertados por la situación actual, Vivian, apresurándose, llama a Vice a un lado, hablando de una misión inmediata en sus manos. Llegan a la Estación Illumina y descubren que acompañando a Vice en esta misión no solo está Charon, sino también tres concursantes que afirman venir de Umbraton. Al escuchar esto, una sensación de inquietud invade tu corazón.",
  str_mission_desc_4207030_long = "Mientras te sumerges en tus pensamientos sobre quién podría guiar el camino de Illumina hacia adelante, la transmisión de repente anuncia el nombramiento de Wrath como el nuevo Gran Mariscal. Entre tu asombro, Leo se apresura a informarte sobre la invasión de los Eclipsites en Crepúsculo. Te ruega que pilotes el Coloso y lo acompañes para brindar ayuda. Mientras tanto, en un laboratorio secreto de Illumina, un plan secreto está en marcha silenciosamente.",
  str_mission_desc_4207031_long = "—",
  str_mission_desc_4207040_long = "Bajo las miradas atentas de los espectadores, el recién nombrado Gran Mariscal, Wrath, lidera a las nuevas fuerzas militares para reunirse en la estación, junto a la avanzada máquina de guerra, Engine VII. Aunque Wrath ahora ocupa la posición que tanto anhelaba, es consciente de que aún no ha triunfado sobre Reinhardt de manera justa. Pensando en eso, los recuerdos de sus pasados desafíos contra Reinhardt comienzan a aflorar en el corazón de Wrath.",
  str_mission_desc_4207050_long = "Con un claro entendimiento de su propia fuerza, Wrath había anticipado desde hace tiempo los resultados de la selección final del Gran Mariscal. A pesar de finalmente ocupar el lugar de Reinhardt, no es el camino que ella esperaba. Por lo tanto, Wrath toma la decisión interna de mantener temporalmente el puesto de Gran Mariscal hasta el regreso de Reinhardt, comprometiéndose a superar su papel en todos los aspectos posibles.",
  str_mission_desc_4207060_long = "Impulsados por la motivación y el ánimo de Joselyne, los soldados se mantienen valientemente en pie frente al ataque de los Eclipsites. Mientras tanto, tú y Leo finalmente llegan a la entrada de Twilight. Aunque Leo es reacio a que te unas a esta terrible batalla, tu ventajoso papel como Caelestite y piloto del Coloso lo convence de lo contrario. Al final, es tu refuerzo el que reaviva la moral de los soldados en el campo de batalla.",
  str_mission_desc_4207075_long = "Planeando solicitar apoyo de Lumopolis, Zhao inadvertidamente se convierte en prisionero de los secuaces de Istvan. En la Corte Real de Lumopolis, Schwartz sostiene varias súplicas de ayuda en su mano, mientras los nobles debaten si enviar refuerzos. Al final, Schwartz ordena a las tropas de apoyo mantener su posición en la Fortaleza Lumo, absteniéndose de participar en las operaciones militares de Illumina.",
  str_mission_desc_4207080_long = "Con el ataque de los Eclipsites intensificándose, incluso el experimentado Leo se encuentra al límite. Justo cuando el grupo debate entre un ataque audaz o una retirada continua, Wrath lidera la Legión de la Guardia Illumina en el campo de batalla, cambiando las mareas de la batalla en Crepúsculo.",
  str_mission_desc_4207090_long = "Forsakin se da cuenta de las \"Semillas\" implantadas en estos soldados, diseñadas para mejorar sus capacidades de combate. A pesar de su descontento con Ulysses por robar sus hallazgos experimentales, se da cuenta de que los formidables Eclipsites traídos por Wraith están a favor de sus acciones posteriores. Mientras tanto, sientes el aumento de un enorme Darkflow, pero aún desconoces que la pesadilla en Crepúsculo apenas ha comenzado.",
  str_mission_desc_4207100_long = "Al investigar las anomalías entre los soldados de Illumina, Leo y Wrath tienen una acalorada discusión sobre los problemas dentro de las filas de sus fuerzas. Con la esperanza de descubrir la causa de las anomalías de los soldados, Wrath busca tu ayuda. Mientras te adentras en la conciencia de un soldado corrompido y encuentras un lodazal sin límites dentro, en el mundo real, Crepúsculo también sufre la incursión implacable del barro y los Eclipsites.",
  str_mission_desc_4207110_long = "Al presenciar el terrible destino de los soldados siendo devorados por los Eclipsites durante el experimento, Yingel finalmente comprende el verdadero propósito del \"Programa Phospherus\": ¡Están implantando \"Semillas\" en los Aurorianos y seleccionando soldados excepcionales mediante combates contra Eclipsites! Justo cuando Yingel intenta detener el experimento, un sujeto fuera de control lanza repentinamente un violento ataque contra ellos.",
  str_mission_desc_4207111_long = "—",
  str_mission_desc_4207120_long = "Después de una exhaustiva investigación del campo de batalla junto a Wrath, gradualmente descubres por qué los soldados de Illumina son propensos a la influencia del lodo. Mientras tanto, el lodo se extiende implacablemente hacia Twilight, ya que el enemigo que actúa como centro de comando aprovecha la oportunidad para lanzar un ataque. Con Wrath liderando la carga, tomas el mando en el campo de batalla pero accidentalmente quedas atrapado por el lodo.",
  str_mission_desc_4207130_long = "Mientras observas a Wrath lanzarse imprudentemente en medio de los Eclipsites, decides emplear un Force Boost para entrar en su conciencia y despertarla desde dentro. Desde una sala de consejo suprimida hasta la empapada ciudad de Gannon, y la vista de Reinhardt tendido en una mesa de operaciones... Finalmente, en medio de las escenas siempre cambiantes de la conciencia de Wrath, logras localizar su presencia.",
  str_mission_desc_4207140_long = "Tú y Wrath finalmente localizan al último escuadrón de las fuerzas de Illumina. Animada por las palabras de Wrath, Axelia recupera gradualmente su movilidad. Después de vuestra exhaustiva búsqueda, el enemigo principal se revela, mientras Leo llega liderando a los Caballeros de la Expedición. Sin embargo, para proteger a su equipo de la influencia corruptora del lodo, Wrath decide enfrentarse al enemigo por sí misma.",
  str_mission_desc_4207155_long = "Hace solo unos días, Wrath recibió una notificación del Comité: suceder a Reinhardt como el nuevo Gran Mariscal de Illumina, con la condición de participar en el \"Programa Phospherus\". Con su aspiración casi al alcance, Wrath se dio cuenta de que sus ambiciones estaban experimentando una transformación silenciosa. Al final, aceptó los términos del Comité, pero también se formó un plan en secreto en su corazón.",
  str_mission_desc_4208015_long = "Más allá de las fronteras de Crepúsculo, también están ocurriendo cambios. Mientras el Equipo de Reconocimiento de Illumina sigue la pista del núcleo de \"Guardián Uno\", se encuentran con pistas inesperadas y cruciales. Mientras tanto, dentro de la Corte Real de Lumopolis, Hydrad, actuando como enviado de Istvan, discute con Schwartz asuntos de refuerzo. Finalmente, Schwartz toma una decisión: proteger a los Aurorians al estilo de Lumopolis.",
  str_mission_desc_4208020_long = "Bajo la influencia del lodo, algunos soldados de Illumina mutan en Eclipsites, lanzando ataques contra sus propios compañeros. Ante este grave escenario, Leo organiza la evacuación de los subordinados de Wrath mientras se ocupa personalmente de los soldados transformados. En medio del caos, el herido Wrath regresa a la lucha, intentando recuperar a aquellos atrapados en un frenesí rabioso.",
  str_mission_desc_4208030_long = "Dado los recursos médicos limitados en Crepúsculo, decides dividirte en tres equipos para la operación de rescate. Wrath continúa la búsqueda de los soldados Illumina desaparecidos, mientras Joselyne escolta a los soldados heridos de gravedad para buscar refugio en el Bastión Lumo. En cuanto a ti, Leo inicialmente sugiere que pilotes el Coloso y lleves a los refugiados a un lugar seguro en Eraveil, pero te mantienes firme, insistiendo en quedarte para enfrentar la tormenta con todos.",
  str_mission_desc_4208040_long = "Charon parece haber anticipado la llegada de Victoria, pero se sorprende al saber que la extraña resistencia encontrada no es obra de Victoria. Vice, al conocer la situación en Twilight, se preocupa por tu seguridad y, con la ayuda de Victoria, viaja al pueblo. Sin embargo, después de una breve estancia, la extraña fuerza ataca el tren de Charon una vez más.",
  str_mission_desc_4208041_long = "—",
  str_mission_desc_4208050_long = "La revelación del Bloody Bible deja a todos desconcertados. Victoria rápidamente se da cuenta de que el \"Dominio\" del Wraith ha envuelto al tren. Para escapar del \"Dominio\", Charon lucha contra el Wraith de frente, mientras Victoria y tres de sus subordinados realizan un rito sacrificial para liberarse del aprieto. Justo en el momento en que Vice rompe el cerco, tu habilidad psíquica capta el ritmo del latido del corazón de Vice.",
  str_mission_desc_4208060_long = "Tienes la intención de salvar a este soldado con tu habilidad psíquica. Sin embargo, a pesar de presenciar las experiencias previas a la batalla del soldado, aún no puedes detener su descenso a la locura. En ese preciso momento, los soldados comienzan a enloquecer uno tras otro. Mientras Leo sugiere que él irá a acabar con ellos, Wrath, tomando posición como Gran Mariscal, elige personalmente conceder un final misericordioso a aquellos camaradas atormentados sin medida.",
  str_mission_desc_4208070_long = "Al abrirse la puerta de la ciudad, un rayo de luz sobrenatural hace que todos se inclinen en reverencia. La devota Joselyne reconoce esto como el resplandor divino traído por la \"Santa\" del Templo de Lumopolis. La \"Santa\" atiende a los heridos, reconoce los esfuerzos de Joselyne y decide viajar con ella a Crepúsculo para ayudar a aquellos que aún lo necesitan.",
  str_mission_desc_4208080_long = "Forsakin se ríe, diciendo que estos soldados caídos son su \"obra de arte\" meticulosamente creada para que todos la vean. La ira de Wrath arde, pero no actúa imprudentemente, consciente de la influencia de la \"Semilla\" en su cuerpo. En su camino para recuperar a los soldados que Forsakin ha arrebatado, Axelia es testigo del espantoso espectáculo de soldados enfrentándose entre sí. En el momento más crítico, llega un equipo de refuerzo.",
  str_mission_desc_4208095_long = "Vivian reconoce a Anatoli como la fuente de la señal y recuerda cómo él la había obstaculizado durante una misión en la prisión de Illumina. Resulta que Anatoli empleó este mismo método para probar la determinación de Vivian y finalmente decide ayudarla a completar su plan. Justo cuando los dos creen que el plan avanza sin problemas, la señal se interrumpe bruscamente.",
  str_mission_desc_4208100_long = "La batalla en Crepúsculo consolida la determinación de Leo de ser el guardián del pueblo. Joselyne, muy consciente de los conflictos entre facciones, expresa a la \"Santa\" su resolución de establecer un refugio para los aurorianos dentro de la iglesia. Sin embargo, la guerra está lejos de terminar. Al enterarse de que múltiples fuerzas se han unido en las defensas de Illumina, todos deciden reagruparse y avanzar hacia la línea de defensa.",
  str_mission_desc_4208110_long = "En medio de la intensa batalla de los soldados, Barton y Hiiro llegan como refuerzos. Después de compartir la situación actual, Sharona sigue preocupado por la seguridad de Wrath. Sin embargo, la aparición oportuna de Reinhardt fortalece la confianza de todos. Resulta que el plan de Wrath no solo implica defender el Crepúsculo, sino también rescatar a Reinhardt y reagruparse con ellos en el frente de batalla.",
  str_mission_desc_4208111_long = "—",
  str_mission_desc_4208120_long = "Wrath tiene la intención de liderar a sus tropas y rodear al ejército Eclipsite, pero \"Engine VII\", bajo la influencia del Darkflow, se convierte en un obstáculo inesperado. Justo cuando Axelia está en apuros luchando contra \"Engine VII\", Reinhardt acude al rescate. Con una mezcla de satisfacción y alivio, Reinhardt observa cómo Wrath se reincorpora al frente de batalla, pero Wrath se hace a un lado voluntariamente, dejando a Reinhardt tomar las riendas para dirigir la batalla en desarrollo.",
  str_mission_desc_4208130_long = "—",
  str_mission_desc_4208140_long = "Antes de retirarse, Forsakin, manipulando tanto a los soldados de Illumina como a Engine VII, lanza un último y brutal ataque contra el ejército de Illumina. Reinhardt percibe la participación de Forsakin en la operación de Eclipse e intenta razonar con ella, instándola a cumplir con su propia voluntad. Sin embargo, la respuesta de Forsakin provoca una creciente brecha entre las que alguna vez fueron hermanas. Poco después, los soldados de Lumopolis y Twilight se unen a la batalla en la línea de defensa.",
  str_mission_desc_4208155_long = "La lluvia cae sobre el frente de Illumina. Al cesar, el barro se disipa, revelando la tierra bajo el sol una vez más. Wrath contempla las numerosas bajas, culpándose a sí misma por su fracaso como Gran Mariscal. Sin embargo, Reinhardt elogia su desempeño, afirmando que fue su inquebrantable determinación la que protegió a Crepúsculo y a sus soldados. No obstante, la verdadera batalla aún se avecina.",
  str_mission_limit_4000001 = "Navegador, ¡ve a luchar y completa la fase con <color=#e8d9bb>Vice</color>!",
  str_mission_limit_4000002 = "Despliega tus miembros del escuadrón y lucha con <color=#e8d9bb>Vice</color> ¡juntos!",
  str_mission_limit_4000003 = "Será mejor que desp. otros com. de eq. para completar la fase con <color=#e8d9bb>Vice</color>. ¡Pruébalo!",
  str_mission_leader_limit_4000002 = "Navegador, <color=#e8d9bb>¡Vice</color> es la mejor candidata de Capitán!",
  str_mission_desc_4209015 = "—",
  str_mission_desc_4209020 = "Una pesadilla vívida te despierta sobresaltado varios días después en las primeras horas de la madrugada...",
  str_mission_desc_4209030 = "En tu emoción, te vas sin obtener una hora o ubicación para la cita, y las cosas ciertamente no se ven bien en Illumina en este momento...",
  str_mission_desc_4209040 = "Te sorprende cómo Algol hace su debut, pero te sorprende aún más su \"mascota\" parásita.",
  str_mission_desc_4209050 = "Tú y Vivian quedan asombrados cuando Algol los lleva a su oficina. ¿Realmente existe un lugar así en Illumina?",
  str_mission_desc_4209065 = "—",
  str_mission_desc_4209070 = "Varios Eclipsites aparecen repentinamente en el Parque Tecnológico Illumina y bloquean tu camino...",
  str_mission_desc_4209080 = "Los Eclipsites siguen saliendo del edificio, pero lo que te sorprende más es que Ulysses está siguiendo silenciosamente detrás de ellos...",
  str_mission_desc_4209081 = "Parece que estos Soldados Illumina sufren una temible transformación por la noche. ¡Ten cuidado!",
  str_mission_desc_4209090 = "Las palabras de Ulysses están cargadas de amenazas, y has visto peligro en sus visiones...",
  str_mission_desc_4209100 = "Durante la quinta conferencia de revisión, Ulysses rememora un capítulo de su pasado...",
  str_mission_desc_4209115 = "—",
  str_mission_desc_4209120 = "¿Qué tiene que ver ese prototipo sellado hace mucho tiempo con Ulysses?",
  str_mission_desc_4209121 = "Estos Eclipsites tienen capacidades de contraataque muy mejoradas, así que intenta no enfrentarte a ellos en combate cuerpo a cuerpo.",
  str_mission_desc_4209130 = "En su emoción por leer las notas del Ingeniero, Ulysses se alejó cada vez más de su propia investigación...",
  str_mission_desc_4209140 = "A través de la computadora de Ulysses, has descubierto que accedió a un almacén no registrado sin autorización...",
  str_mission_desc_4209150 = "Después de derrotar a los súper soldados, diriges tu atención al prototipo que aún está en funcionamiento...",
  str_mission_desc_4210015 = "—",
  str_mission_desc_4210020 = "Ulysses insiste en que sus experimentos benefician a Illumina y se esfuerza por demostrar su punto, pero eso desagrada severamente a Anatoli, que está justo cerca...",
  str_mission_desc_4210030 = "Para acelerar el descifrado, te has conectado mentalmente con Bool para encontrar pistas.",
  str_mission_desc_4210045 = "—",
  str_mission_desc_4210050 = "Justo cuando Algol piensa que has recopilado suficiente información, aparece un factor X...",
  str_mission_desc_4210060 = "¿Qué sucederá cuando inicies sesión en el sistema del Guardián?",
  str_mission_desc_4210070 = "Cuando estalla una crisis, algunas personas entran en pánico, y otras simplemente no pueden esperar...",
  str_mission_desc_4210071 = "El lugar donde los Soldados Illumina están realizando su misión secreta parece ser Lumópolis...",
  str_mission_desc_4210080 = "Ulysses llega al Almacén Cero y abre ansiosamente el regalo que ha estado preparando durante años...",
  str_mission_desc_4210090 = "Al escuchar ese sonido, de repente te das cuenta del significado de esos sueños tan vívidos pero surrealistas...",
  str_mission_desc_4210100 = "Sales precipitadamente sin pensar, solo para encontrarte a ti mismo habiendo perdido la percepción de ello...",
  str_mission_desc_4210110 = "Las burlas del enemigo te han enfurecido. ¿Qué respuesta darás como Celestita?",
  str_mission_desc_4210120 = "El Ingeniero ha mostrado signos de retroceder, pero aún falta el núcleo de defensa de Gannon. ¿Qué hacer ahora?",
  str_mission_desc_4210121 = "Los poderosos super soldados pueden potenciar a todos tus enemigos, ¡así que debes detenerlos!",
  str_mission_desc_4210130 = "Después de que se reemplace el núcleo, escuchas a Ulysses hablar en un idioma totalmente extranjero...",
  str_mission_desc_4210140 = "Antes de que su visión colapse, recuerda una conversación en tiempo de guerra en el sanatorio...",
  str_mission_desc_4210155 = "—",
  str_mission_desc_4209015_long = "Después de un violento temblor, tú y los soldados de Crepúsculo regresan a Eraveil después de una larga ausencia. Los supervivientes de Crepúsculo preparan un festín abundante; después de saciarte con una comida perfecta, comienzas una conversación con Soroz.",
  str_mission_desc_4209020_long = "Preocupado por la seguridad de Vice, te sientas en tu terminal de Colossus durante días, esperando ansiosamente cualquier noticia de Reinhardt. De repente, finalmente recibes ese mensaje tan esperado.",
  str_mission_desc_4209030_long = "Como resultado de un problema con el sistema de defensa de Illumina, eres atacado por Eclipsites en el patio de servicio de Illumina. Justo entonces, la persona que te invitó aquí aparece de una manera más inesperada.",
  str_mission_desc_4209040_long = "Algol presenta a su compañero Bool, y explica sus razones para invitarte a Illumina. Sugiere que los archivos de datos de Soroz pueden contener pistas sobre el Núcleo de Guardian One, lo que esperamos conduzca a descubrir el paradero de Vice.",
  str_mission_desc_4209050_long = "Mientras tomas una taza de café preparada por Guardian One, Vivian parece finalmente relajarse un poco. Después de un breve descanso, todos se ponen a trabajar. Desafortunadamente, nadie te contó sobre el método de comunicación único y bastante doloroso de Bool...",
  str_mission_desc_4209065_long = "Después de un análisis exhaustivo, descubres un conjunto de coordenadas parpadeantes ocultas dentro de los archivos de datos de Soroz, que parecen ser anteriores a Eraveil por bastante tiempo. Algol sospecha que el lugar de nacimiento de los Colosos se encuentra en lo profundo de la Zona Oscura, por lo que te acercas a uno de los físicos expertos de Illumina para preguntar sobre las coordenadas.",
  str_mission_desc_4209070_long = "Después de derrotar a los Eclipsites, descubres que sus cuerpos tienen un sorprendente parecido con los de los Aurorianos. Barton, que estaba patrullando el Parque Tecnológico de Illumina, se une a tu grupo y todos suponen que estos Eclipsites eran probablemente sujetos de prueba escapados del laboratorio de Ulysses. Con la ayuda de Alglol, te diriges al laboratorio y te preparas para interrogar al investigador.",
  str_mission_desc_4209080_long = "Ulysses no niega que los Eclipsites de antes hayan escapado de su laboratorio, y te invita a adentrarte más en el edificio para lo que él llama un \"pequeño experimento\". Curioso acerca de varias cosas que mencionó, aceptas su invitación.",
  str_mission_desc_4209090_long = "Después de presenciar una escena peligrosa y horrorosa, Ulysses es llevado por las autoridades de la Federación Illumina. Aunque todavía no estás seguro de por qué te mostró estas cosas, parece que el sol comienza a brillar nuevamente en Ciudad Gannon. Tú y tus amigos esperan que esta crisis termine pronto.",
  str_mission_desc_4209100_long = "Hace años, un joven Ulysses se dedicó a mejorar la supervivencia de los aurorianos. Mientras investigaba la tecnología de ingeniería genética de Illumina, que se había transmitido desde hace siglos, descubre un nombre olvidado por la historia. Ver este nombre le llena de esperanza para el futuro de todos los aurorianos.",
  str_mission_desc_4209115_long = "Joyce te habla sobre una piedra flotante, que había aparecido en las coordenadas dentro de la Zona Oscura, y la información coincide con las imágenes que viste en la mente de Ulysses. Solo entonces Algol se da cuenta de que Ulysses ha estado ocultando su trabajo en el prototipo del Guardián todo el tiempo.",
  str_mission_desc_4209120_long = "En la audiencia, todos se sorprenden al descubrir que Ulysses ha estado investigando secretamente sobre la máquina antigua. A medida que se desarrollan estas revelaciones, tú y Algol continúan buscando en la Ciudad de Gannon el prototipo. Sin embargo, tan peligrosos como esta máquina, son los super-soldados que emiten Darkflow escondidos en las sombras.",
  str_mission_desc_4209130_long = "Ulysses propone un experimento audaz, lo que hace que Robby, su colega de mucho tiempo, lo sospeche. ¿Quién es \"el Ingeniero\" y cómo convenció a Ulysses para que tomara medidas tan radicales con su investigación?",
  str_mission_desc_4209140_long = "Cuando Algol llega al Almacén Cero, se emociona al descubrir que el prototipo de Guardián aún está operativo. Desafortunadamente, tu intrusión también desencadena un ataque por parte de los super soldados almacenados en el edificio.",
  str_mission_desc_4209150_long = "Cuando Algol vio por primera vez el prototipo, todavía era estudiante de Ulysses. Sin embargo, lo más sorprendente es el hecho de que Ulysses lo mantuvo operativo en su almacén privado incluso después de que fue sellado por razones de seguridad. Mientras tú y tus amigos intentan acceder al misterioso prototipo, se llenan de una mezcla de anticipación y temor.",
  str_mission_desc_4210015_long = "Te sorprenden las impresionantes funciones y velocidad de procesamiento de Bool. A medida que Algol relata la historia de cómo se conocieron por primera vez, lentamente te das cuenta del significado detrás de las etiquetas en su cuerpo.",
  str_mission_desc_4210020_long = "Se revela que el verdadero propósito de la Subciudad 80 era seleccionar candidatos para el proyecto del Sol Artificial. Mientras recopila información crucial sobre el proyecto, el equipo de reconocimiento de Anatoli es finalmente aniquilado. Sin querer aceptar la pérdida de su equipo, Anatoli exige que el Comité intente y castigue a Ulysses por sus crímenes.",
  str_mission_desc_4210030_long = "Después de usar tus poderes psíquicos en Bool, te sientes abrumado por una oleada interminable de números y secuencias. Para extraer la información que necesitas, Algol comparte contigo su truco para manejar cargas de trabajo difíciles. Lo intentas de nuevo, y al parecer logras obtener algunos datos útiles.",
  str_mission_desc_4210045_long = "Al igual que Yingel y Axelia, Sean también es un producto del Programa Phospherus. Sin embargo, a Sean se le consideró un fracaso al inicio del programa y fue enviado a Twilight. Después de conocer sus orígenes, Sean comienza a preguntarse si su propósito en la vida es convertirse en un arma de guerra despiadada.",
  str_mission_desc_4210050_long = "Vincularse con la mente de Bool te causa un mareo y malestar no pequeños. Algol te da un límite de dos minutos, durante los cuales se te instruye para recuperar la mayor cantidad de información posible. Afortunadamente, sales relativamente ileso, pero algo parece estar preocupando a Algol. ¿Qué en el mundo podría haber derribado una civilización lo suficientemente avanzada como para crear esta tecnología?",
  str_mission_desc_4210060_long = "Te toma desprevenido la situación en Ciudad Gannon. Algol continúa buscando desesperadamente una forma de entrar en el sistema, solo para descubrir que los violentos temblores son causados por un enemigo invisible. El juicio de Ulysses también se suspende temporalmente. Justo cuando crees que la crisis está casi superada, el enemigo invisible aparece en la pantalla del prototipo...",
  str_mission_desc_4210070_long = "Ulysses afirma haber ideado ya una forma de derrotar al enemigo, y Belisaria está de acuerdo con su operación, cambia los preparativos anteriores y lanza urgentemente el plan preestablecido.",
  str_mission_desc_4210080_long = "Los súper soldados almacenados en el almacén son el resultado de los años de investigación científica de Ulysses, así como su regalo para el Ingeniero. Sin embargo, para sorpresa de Ulysses, el Ingeniero pronto toma el control de ellos y los usa para atacar a todos los compatriotas de Illumina.",
  str_mission_desc_4210090_long = "\"Vuelve a casa, Caelestite\". Un mensaje críptico para muchos, pero uno que has escuchado en tus sueños innumerables veces. ¿Quién es él? ¿A dónde exactamente quiere que vayas? Mientras luchas al límite de tu ingenio, de repente recibes noticias de que Soroz ha sido activado.",
  str_mission_desc_4210100_long = "El momento de la despedida finalmente ha llegado, pero no sientes nada. Por razones desconocidas, has jugado este escenario en tu mente más veces de las que puedes contar. El peligro sigue de cerca a tu tristeza, pero un pequeño amigo interviene y bloquea un golpe fatal destinado a ti.",
  str_mission_desc_4210110_long = "Dentro de la conciencia de Figerald, pareces presenciar el proceso por el cual el Ingeniero esclaviza a otros. No solo eso, ves recuerdos lejanos de un abismo bostezante y restos esqueléticos de Colosos emergiendo de la mente de Figerald...",
  str_mission_desc_4210120_long = "Para proteger la ciudad de Gannon, el compañero de Algol, Guardian One, ofrece resueltamente su propio Núcleo. Mientras tanto, para obtener suficiente potencia de cálculo para la transición, Reinhardt promulga un protocolo de emergencia para redirigir la potencia de procesamiento de cada computadora en la ciudad de Gannon a su ubicación.",
  str_mission_desc_4210130_long = "Algol descubre que el lenguaje informático utilizado por el Sistema Guardian está de alguna manera relacionado con el lenguaje utilizado por los Eclipsites. Ulysses se jacta de que puede cambiar el mundo entero, pero tú no tienes ningún deseo de vivir en un mundo modificado por sus manos.",
  str_mission_desc_4210140_long = "¿Qué es más trágico, la pérdida de fe o la incapacidad para realizar los sueños? Ulysses te hace una última pregunta antes de caer a tus pies. Ya no puede responder, esta puede ser la última vez que se plantea esta pregunta.",
  str_mission_desc_4210155_long = "Después de estar inconsciente durante tres días, despiertas para descubrir que la crisis en Ciudad Gannon ya ha pasado. Sin embargo, lo que te espera ahora es una misión de exploración aún más peligrosa. Recuerdas cómo fuiste salvado mientras usabas tus poderes, y te preguntas si alguien en ese espacio brillante y parecido a un lago puede ofrecerte la orientación que buscas.",
  str_mission_desc_4301015 = "—",
  str_mission_desc_4301020 = "Dentro de un vasto centro de comando temporal, el Comité de la Expedición Conjunta Astra convoca una conferencia crucial sobre el futuro de los Aurorians.",
  str_mission_desc_4301030 = "Debido a encontrarse con corrientes de aire extremas, tu avión cae inesperadamente en las llanuras nevadas en el borde de Northland...",
  str_mission_desc_4301040 = "Sigues el rastro de sangre, pero misteriosamente desaparece en el camino...",
  str_mission_desc_4301055 = "Mientras Bethlehem te escolta fuera de la cueva, ella percibe el campo de energía único dentro y diseña una solución para superar el aprieto.",
  str_mission_desc_4301060 = "Ante la crisis actual en Northland, Bethlehem busca el consejo del Anciano de la Nieve Fox sobre cómo despertar el Refugio Primordial para limpiar la contaminación que asola las llanuras de nieve.",
  str_mission_desc_4301070 = "—",
  str_mission_desc_4301080 = "Mientras la intensa nieve cubre la frontera, llegas a la tribu que crió a Tiare, comenzando a buscar el tercer pino.",
  str_mission_desc_4301090 = "Con el despertar del Refugio Primordial, se erige un nuevo faro. Tiare blandiendo su poderosa lanza, cargando una vez más hacia ese poderoso Eclipsite.",
  str_mission_desc_4301105 = "—",
  str_mission_desc_4301015_long = "Bethlehem recuerda un encuentro pasado. Hace años, mientras patrullaba el Bosque de Snowpine en el borde de Northland, tuvo un breve encuentro con el Snow Fox que vivía allí. Tiare, el niño criado por ese Snow Fox, ahora sirve como guardia de Bethlehem, viviendo en el Palacio de Invierno, pero aún se preocupa por su tribu.",
  str_mission_desc_4301020_long = "Delegados de Lumopolis, Umbraton y la Unión de Mensajeros han intercambiado opiniones sobre los preparativos de exploración de la Federación Illumina. Después de la reunión, Reinhardt te asigna a ti y a Carleen para investigar el estado de establecimiento del puesto avanzado de Northland.",
  str_mission_desc_4301030_long = "Accidentalmente tropiezas en el territorio de la tribu fronteriza, te desconciertan las manchas de sangre esparcidas por el suelo. Las reacciones subsiguientes de Tiare y los Zorros de Nieve sugieren que las cosas no son tan simples como parecen. A pesar de su vehemente oposición, aún decides seguirlos para ver qué fue exactamente lo que sucedió.",
  str_mission_desc_4301040_long = "Superando tus miedos internos, empleas tus habilidades psíquicas para rastrear a Tiare y los zorros de nieve. Finalmente, te encuentras con las manchas de sangre que dejaron y descubres inesperadamente que dos de tus amigos de Rediesel Wrench también han venido a Northland con tu avión. Pero lo que no sabías es que un poderoso Eclipsite se esconde cerca.",
  str_mission_desc_4301055_long = "Liderado por el Anciano Fox de la Nieve, llegas al antiguo altar custodiado por la tribu Fox de la Nieve durante generaciones. Aquí, tu fuerza resuena con el poder antiguo, y se despliega la leyenda de los \"Tres Pinos\". Para sorpresa del Anciano Fox de la Nieve, no fue la familia real quien tomó los pinos, sino que los pinos eligieron a la familia real y reconocieron a la reina.",
  str_mission_desc_4301060_long = "Mientras Bethlehem se enfrenta solo al Eclipsite, decides buscar dos otros pinos junto con Tiare. Novio sugiere que, dado que el antiguo poder ha disminuido, para encontrar los pinos, debes buscar pistas en la leyenda de los \"Tres Pinos\".",
  str_mission_desc_4301070_long = "Llevándote sobre sus hombros, Tiare corre todo el camino, llegando finalmente a la Corte de Northland. Cuando estás perdido, las palabras de Zarya ofrecen una pista. Resulta que el pino talado hace tiempo que se ha convertido en el trono de la reina, pero como la reina nunca se sienta en él, el trono ha estado acumulando polvo en la corte.",
  str_mission_desc_4301080_long = "Al adentrarte en los recuerdos de Tiare, descubres el desacuerdo entre el Anciano de la Nieve Fox y la abuela de Tiare con respecto a su futuro. El problema clave de su disputa es algo sobre una losa de piedra que simboliza un compromiso antiguo, que es precisamente lo que estás buscando. Con la ayuda de Tiny One y Roy, logras localizar el tercer pino y lo llevas de vuelta al altar.",
  str_mission_desc_4301090_long = "El ataque de Tiare despierta recuerdos en el Eclipsite, recordándole su pasado y las razones detrás de su entrenamiento implacable. Mientras intenta un golpe final contra ti, lo expulsas de Northland. Bajo la luz del Faro, das un paso histórico hacia adelante, aventurándote en la Zona Oscura.",
  str_mission_desc_4301105_long = "A pesar de que el Eclipsite sigue invicto y el puesto avanzado de Northland aún está en construcción, decides hacer preparativos activos y continuar con tu exploración en la Zona Oscura en el tiempo venidero. Antes de partir, recibes el Mineral Lumina entregado por Tiare. De pie cerca, Bethlehem encuentra consuelo y satisfacción, sabiendo que el guardia de Northland, Tiare, ha crecido y madurado.",
  str_mission_desc_4220015_long = "Mientras tu avión surca la noche, siguiendo al equipo de expedición y a Vice, una misteriosa bola de luz ha captado tu atención. Mientras tanto, Reinhardt y el Comité están tomando medidas. Una nueva \"sombra\" está ahora en el centro de atención.",
  str_mission_desc_4220020_long = "Te encuentras con el equipo de Pepita en la Zona Oscura, pero ella huye en el momento en que te ve. La inteligencia de Philyshy revela que Pepita es buscada tanto por Illumina como por Lumopolis. Poco después, aparece el equipo de Lumopolis. Ya han lidiado con ella antes, pero el Comité intervino antes de que pudieran arrestarla la última vez.",
  str_mission_desc_4220030_long = "Pepita aparece y engaña a todos. No solo no se ve afectada por la Zona Oscura, sino que ahora está del lado del Wraith y tiene un familiar poderoso de ellos. Después de agitar las cosas, se va casualmente con el Wraith, del brazo.",
  str_mission_desc_4220040_long = "Pepita recuerda su infancia, cuando su papá la traicionó y vivió una vida controlada por el Comité. Reemplazaron su frágil corazón con uno artificial fuerte, dejándola sin otra opción que seguir sus órdenes. A pesar de todo, ella todavía no quiere lastimar a otros.",
  str_mission_desc_4220050_long = "La condición de Pepita es hereditaria, pero después de que su padre la vendiera al Comité, dejó de confiar en Illumina y terminó rebelándose y uniendo a la Orden Verdadera. Mientras que Reinhardt y Schwartz quieren hacerla volver al buen camino, el Capitán de la División de Investigación de Herejes no está tan seguro de eso.",
  str_mission_desc_4220060_long = "Guiado por el tesoro del Capitán de la División de Investigación de Herejes, te encuentras en una zona desconocida. Parece que los Aurorianos vivieron aquí una vez, pero se han ido hace mucho tiempo.",
  str_mission_desc_4220070_long = "Tocas el cadáver y vislumbras el pasado de la Tribu Tundra. Estas personas estaban atrapadas por el coral de Ursura, pasando toda su vida trabajando para una cierta horno sin libertad. De vez en cuando, Yodu, un Fantasma, revisaba su progreso. Pero un día, Yodu decidió que ya no valían la pena y masacró a todos.",
  str_mission_desc_4220085_long = "Pepita, atrapada con un corazón controlado por el Comité, mira con envidia el corazón de coral de Ursura. Ursura le hace una oferta: si Pepita acepta ser suya para siempre, le hará un corazón de coral. Recordando su primer encuentro, Pepita decide que nunca se someterá a nadie.",
  str_mission_desc_4220090_long = "Pepita se adhiere a su principio de \"ser libre o estar muerto\" y corta lazos con Ursura.\nEncuentras una barrera que bloquea a Darkflow, pero de repente, Victoria aparece, reclamándola como suya. A medida que las cosas se calientan, Ursura aparece persiguiendo a Pepita—pero curiosamente, se asusta y huye en el segundo que ve a Victoria.",
  str_mission_desc_4220100_long = "El equipo de expedición no pudo ponerse de acuerdo sobre si atacar a Victoria, lo que provocó que el grupo se separara. El Capitán de la División de Investigación de Herejes se lanza solo contra Victoria y es derrotado. Victoria luego revela una verdad, ahora finalmente te das cuenta de que la luz que te guiaba todo el tiempo era Vice, quien había caído en las profundidades del Río Prístino.",
  str_mission_desc_4220110_long = "Victoria va tras Ursura solo y la enfrenta en una pelea. Bajo la técnica secreta de Victoria, Ursura es fácilmente derrotada.\nMientras tanto, Charon se encuentra con un \"pariente muerto\" llamado Wilhelm. Para salvar a Vice, Charon traga su orgullo y comienza a aprender la técnica secreta del vampiro de él.",
  str_mission_desc_4220125_long = "Pepita regresa a la base pero es perseguido por el Capitán de la División de Investigación de Herejes y el Verdugo del Comité...\nEn lo profundo de la noche eterna, Figerald es de alguna manera reensamblado por los miembros de Eclipse, solo para ser utilizado como escalones para que Forsakin se convierta en un Fantasma.\nCon la resurrección de Ursura, los nuevos miembros de Eclipse se reúnen, discutiendo la técnica secreta de Victoria...Después de caer del acantilado, Pepita es salvada por su familiar, haciéndola darse cuenta de que Ursura aún está viva. El tren de Charon también atraviesa el espacio y la localiza...",
  str_mission_error_failed = "Error del Servidor",
  str_mission_error_invalid_level = "Etapa inválida",
  str_mission_error_invalid_power = "Prisma insuficiente ¡Incapaz de desafiar!",
  str_mission_error_not_exist = "Etapa no encontrada",
  str_mission_error_is_lock = "Etapa bloqueada",
  str_mission_error_story_already_active = "Historia disponible",
  str_mission_error_invalid_id = "Etapa inválida",
  str_mission_error_story_invalid_type = "Tipo de etapa inválida",
  str_mission_error_invalid_chapter_award = "Solicitud de recompensa del capítulo inválida",
  str_mission_error_invalid_chapter_award_star = "Estrellas inválidas",
  str_mission_error_invalid_chapter_award_receive = "Recompensa reclamada",
  str_mission_error_invalid_chapter_award_config = "Recompensa reclamada no coincide con la configuración",
  str_mission_error_dirty_name = "Palabras sensibles. ¡Vuelve a ingresar!",
  str_mission_error_power_not_enough = "Poco {1}¡Incapaz de desafiar!"
}
